INSERT INTO `downloads` (`id`, `title`, `category_type`, `file_path`, `file_type`, `file_size`, `download_count`, `created_at`, `updated_at`, `description`, `cover_image`) VALUES
  (5, 'Logo Resmi SMA IT Ishlahul Ummah Prabumulih (High Resolution)', 'Logo', '/uploads/logo-ishum.png', 'PNG', '120 KB', 780, '2026-09-11 15:07:23', '2026-09-11 15:07:23', NULL, NULL),
  (6, 'Logo Lambang Ishlahul Ummah Square HD', 'Logo', '/uploads/logo-ishum-square.png', 'PNG', '85 KB', 316, '2026-09-11 15:07:23', '2026-09-12 08:33:49', NULL, NULL),
  (19, 'Panduan Mutqin Tahfidz Al-Qur\'an 30 Juz SMA IT Ishlahul Ummah', 'E-Book', '/uploads/downloads/panduan-mutqin-tahfidz-ishum.pdf', NULL, '9 KB', 295, '2026-09-12 07:42:35', '2026-09-12 08:10:12', 'Modul resmi kurikulum tahfidz mutqin SMA IT Ishlahul Ummah Prabumulih berbasis standar JSIT Indonesia. Memuat metode ziyadah, jadwal muraja\'ah akbar, target juz kelulusan, dan tata tertib munaqosah terbuka.', '/uploads/covers/cover-tahfidz-mutqin.webp'),
  (20, 'Buku Saku Adab & 10 Karakter (Muwashofat) Santri JSIT', 'E-Book', '/uploads/downloads/buku-saku-adab-karakter-santri.pdf', NULL, '6.9 KB', 280, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Pedoman pembiasaan akhlak islami, adab kepada guru dan orang tua, tata tertib santri asrama dan sekolah, serta 10 Muwashofat Tarbiyah JSIT Indonesia.', '/uploads/covers/cover-karakter-santri.webp'),
  (21, 'Petunjuk Praktikum Laboratorium Sains Terpadu SMA IT Ishum', 'E-Book', '/uploads/downloads/petunjuk-praktikum-sains-terpadu.pdf', NULL, '6.6 KB', 298, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Pedoman eksperimen laboratorium biologi, kimia, dan fisika untuk siswa kelas X-XII SMA IT Ishlahul Ummah yang dilengkapi keselamatan kerja lab dan metode analisis ilmiah Kurikulum Merdeka.', '/uploads/covers/cover-praktikum-sains.webp'),
  (22, 'Kurikulum Pembinaan Da\'i Muda, Khitabah & Public Speaking', 'E-Book', '/uploads/downloads/kurikulum-pembinaan-dai-muda.pdf', NULL, '6.5 KB', 234, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Kumpulan materi public speaking, retorika dakwah 3 bahasa (Indonesia, Arab, Inggris), dan sistematika kultum untuk melatih santri menjadi orator dan pemimpin umat masa depan.', '/uploads/covers/cover-dai-muda.webp'),
  (23, 'Buku Saku Kosakata Harian Bilingual Bahasa Arab & Inggris Santri', 'E-Book', '/uploads/downloads/buku-saku-kosakata-bilingual.pdf', NULL, '6.6 KB', 283, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Modul percakapan bilingual harian asrama dan lingkungan sekolah untuk mempercepat penguasaan active speaking bahasa Arab dan Inggris bagi santri SMA IT Ishum.', '/uploads/covers/cover-bilingual-arab-inggris.webp'),
  (24, 'Panduan Sukses Seleksi Masuk PTN (SNBP, SNBT & Kedinasan)', 'E-Book', '/uploads/downloads/panduan-sukses-snbt-ptn.pdf', NULL, '6.6 KB', 158, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Strategi sukses menembus perguruan tinggi negeri impian, pembedahan materi Tes Potensi Skolastik (TPS), penalaran matematika, literasi bahasa, dan tips memilih prodi realistis.', '/uploads/covers/cover-sukses-snbt.webp');
INSERT INTO `dpcs` (`id`, `name`, `slug`, `description`, `head_name`, `address`, `order`, `created_at`, `updated_at`, `thumbnail`) VALUES
  (1, 'Program Tahfidz Mutqin 30 Juz', 'program-tahfidz-mutqin-30-juz', 'Bimbingan intensif membaca Al-Qur\'an dengan tartil, tahsin bersanad, dan hafalan mutqin serta program Munaqosah TTQ kelas akhir.', NULL, 'Kurikulum Khusus Keislaman', 1, '2026-09-11 15:07:22', '2026-09-12 09:06:06', '/uploads/covers/cover-tahfidz-mutqin.webp'),
  (2, 'Bina Pribadi Islam (BPI) & Karakter Islami', 'bina-pribadi-islam-bpi', 'Halaqah pekanan pembinaan adab, pembiasaan ibadah yaumiyah, dzikir ma\'tsurat, serta penanaman akhlaqul karimah.', NULL, 'Pembinaan Karakter Santri', 2, '2026-09-11 15:07:22', '2026-09-12 09:06:06', '/uploads/covers/cover-karakter-santri.webp'),
  (3, 'Kurikulum Terpadu JSIT & Kurikulum Merdeka', 'kurikulum-terpadu-jsit-merdeka', 'Memadukan standar capaian Kurikulum Merdeka Nasional dengan nilai-nilai Islam Terpadu berstandar JSIT Indonesia.', NULL, 'Integrasi Nilai Islam & Sains', 3, '2026-09-11 15:07:22', '2026-09-12 09:03:31', '/uploads/lab-ishum.webp'),
  (4, 'Program Belajar Bersama Maestro & Riset Sains', 'belajar-bersama-maestro-riset', 'Eksplorasi bakat seni, budaya, sains dan teknologi langsung bersama tokoh dan pakar di bidangnya.', NULL, 'Pengembangan Akademik & Potensi', 4, '2026-09-11 15:07:22', '2026-09-12 09:06:06', '/uploads/covers/cover-praktikum-sains.webp'),
  (5, 'IU Safar & Outing Class Edukatif', 'iu-safar-outing-class', 'Pembelajaran luar kelas berbasis observasi alam, studi kampus, renang, dan rekreasi edukatif untuk memperluas cakrawala siswa.', NULL, 'Outdoor Learning & Wawasan', 5, '2026-09-11 15:07:22', '2026-09-12 09:06:06', '/uploads/covers/cover-sukses-snbt.webp'),
  (6, 'IU Berkhidmat (Bakti Sosial Masyarakat)', 'iu-berkhidmat-bakti-sosial', 'Kiprah nyata santri dalam melayani dan memberikan kontribusi positif bagi masyarakat di Kota Prabumulih.', NULL, 'Kepedulian Sosial & Dakwah', 6, '2026-09-11 15:07:22', '2026-09-12 09:06:06', '/uploads/covers/cover-dai-muda.webp'),
  (7, 'Club Minat & Bakat', 'club-minat-bakat', 'Club ini bertujuan untuk memfasilitasi peserta didik dalam mengembangkan minat/bakat yang dimiliki.nBeberapa pilihan club minat/bakat yang dapat dipilih peserta didik SMAIT Ishlahul Ummah Prabumulih yaitu :n1. Futsaln2. Bulutangkisn3. Melukisn4. DebatnClub minat/bakat ini dilaksanakan setiap sore di hari senin, selasa, dan jum\'at\nn', 'Koordinator Program', 'Pengembangan Bakat & Minat', 1, '2026-09-12 07:03:22', '2026-09-12 09:06:06', '/uploads/covers/cover-bilingual-arab-inggris.webp'),
  (8, 'Takhassus', 'takhassus', 'Program yang bertujuan untuk mempercepat hafalan qur\'an peserta didik dengan target 6 Juz/3 tahun. Program ini berlangsung sebanyak 2x pertemuan dalam seminggu, yaitu hari rabu &amp; kamis pagi selama 1 jam . Peserta takhassus hanya berlaku untuk peserta didik pilihan (yang memiliki kemampuan menghafal cepat dengan penyeleksian/tes)\nn', 'Koordinator Program', 'Program Khusus Tahfidz', 2, '2026-09-12 07:03:22', '2026-09-12 09:03:31', '/uploads/tahfidz-ishum.webp'),
  (9, 'Munaqosah Tahsin & Tahfidhz Qur\'an', 'munaqosah-tahsin-tahfidhz-quran', 'Program ini bertujuan untuk menguji &amp; mengevaluasi bacaan qur\'an (tahsin) dan hafalan qur\'an peserta didik selama pembelajaran.nProgram ini diselenggarakan 1x setiap akhir semester dengan peserta didik terpilih yang telah mencapai target pembelajaran.nMunaqosah tahfidhz dilaksanakan dengan cara mentasmi\'kan / memperdengarkan seluruh hafalan qur\'an yang telah disetorkan/dimiliki.\nn', 'Koordinator Program', 'Evaluasi & Sertifikasi Al-Qur\'an', 4, '2026-09-12 07:03:22', '2026-09-12 09:06:06', '/uploads/covers/cover-tahfidz-mutqin.webp'),
  (10, 'Kunjungan Edukatif', 'kunjungan-edukatif', 'Program ini bertujuan untuk menambah wawasan serta pengalaman peserta didik dalam pembelajaran secara real lifenProgram ini dilakukan dengan mengunjungi tempat-tempat edukatif di sumatera selatan yang dilaksanakan setiap 1x/semester.\nn', 'Koordinator Program', 'Studi Edukasi & Pengenalan Lapangan', 5, '2026-09-12 07:03:22', '2026-09-12 09:03:31', '/uploads/ishum/fasilitas_1377_IMG-20240528-WA0094-scaled.webp'),
  (11, 'Berenang', 'berenang', 'Program ini bertujuan untuk melatih peserta didik mampu melakukan minimal salah satu olahraga sunnah ini yaitu renang.nProgram ini dilakukan 1x/semester dengan mengunjungi wahana renang yang ada di sumatera selatan\nn', 'Koordinator Program', 'Olahraga Sunnah & Kebugaran', 6, '2026-09-12 07:03:22', '2026-09-12 09:03:31', '/uploads/2022/04/img-20221101-wa0010.webp'),
  (12, 'KHUTBAH JUM\'AT', 'khutbah-jumat', 'Alhamdulillah telah terlaksana sholat jum\'at.\nn\nPetugas jum\'at, 1 September 2023\nn\nBilal : M. Abi khatim Al Habsy Lubis bin Muhammad Tasrif Lubis (XI)nKhotib : Alief Rasya Arrafi bin Roni Ardiansyah (XI)nJudul Khutbah : Berbakti Kepada Kedua Orang Tua\nn\nSemoga jum\'at kita hari ini diberkahi oleh Allah SWT🤲\nn\n[gallery ids=\"2878,2879\"]\nn', 'Koordinator Program', 'Praktik Ibadah & Dakwah Santri', 7, '2026-09-12 07:03:22', '2026-09-12 09:03:31', '/uploads/2022/04/hall-sit-ishlahul-ummah.webp'),
  (13, 'IU Taddabur', 'iu-taddabur', 'Program Unggulan IU Taddabur bertujuan melatih dan membina keunggulan santri/siswa dalam Al-Qur\'an, wawasan kepemimpinan, dan lifeskill islami.', 'Koordinator Program', 'Tadabbur Alam & Penguatan Iman', 8, '2026-09-12 07:03:22', '2026-09-12 09:03:31', '/uploads/campus-ishum.webp'),
  (14, 'BBM', 'bbm', 'Program Unggulan BBM bertujuan melatih dan membina keunggulan santri/siswa dalam Al-Qur\'an, wawasan kepemimpinan, dan lifeskill islami.', 'Koordinator Program', 'Bina Baca Mandiri & Literasi Qur\'an', 9, '2026-09-12 07:03:23', '2026-09-12 09:03:31', '/uploads/2022/04/ruang-belajar.webp');
