  (1, 'PAS Ganjil TA. 2022/2023', 'pas-ganjil-2022-2023', 'Berikut Jadwal Pelaksanaan Ujian AKhir Semester atau Penilaian Akhir Semester (PAS) Ganjil TA. 2022/2023', NULL, 'publish', '/uploads/2022/03/20221129-085235-scaled.webp', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (2, 'PPDB T.A. 2024/2025 Telah Dibuka', 'ppdb-t-a-2024-2025-telah-dibuka', 'Penerimaan peserta didik baru (PPDB) SMA Islam Terpadu Ishlahul Ummah Prabumuluh Tahun Akademik 2022/2023 telah dibuka, silahkan lakukan pendaftaran secara offline ke kantor kami atau secara online dengan cara klik link berikut ini : https://ppdb.smaitishumpbm.sch.id', NULL, 'publish', '/uploads/2023/11/smaitishumpbmsch-id.webp', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
