INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `status`, `type`, `featured_image`, `views_count`, `author_id`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES
  (255, 'IU Safar 2025', 'iu-safar', '<p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\"><strong>SMA IT Ishlahul Ummah</strong> – baru-baru ini menyelesaikan sebuah proyek belajar yang unik dan edukatif : kegiatan <strong><em>IU-Safar</em></strong> &nbsp;ke Kota Palembang. Kegitaan ini dirancang khusus untuk mengenalkan siswa pada <strong>transportasi umum perkotaan, kekayaan kuliner daerah, dan menumbuhkan minat literasi</strong> melalui kunjungan ke toko buku Gramedia World Palembang dan belajar proses pengilingan padi di pabriknya.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Perjalanan petualangan ini dimulai tepat pukul <strong>06.00 WIB</strong> dari <strong>Prabumulih, </strong>dan tiba di palembang sekitar jam 08.30 WIB dan langsung melaksanakan sholat dhuhah di masjid terdekat. Setelah sholat Dhuhah siswa ditantang untuk secara mandiri menggunakan <strong>LRT (Light Rail Transit)</strong> dan angkutan umum lainnya. Mereka belajar membeli tiket, membaca peta rute, dan berinteraksi dengan masyarakat lokal.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">\"Tujuan utamanya adalah menumbuhkan kemandirian dan kesadaran akan pentingnya transportasi publik yang ramah lingkungan. Anak-anak berhasil membuktikan mereka bisa menjelajah kota besar tanpa bergantung pada kendaraan pribadi,\" ujar <strong>Ust Nadirin (mentor siswa) </strong></p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Perjalanan edukatif ini juga menjadi ajang eksplorasi kuliner. Titik fokus utamanya adalah mencicipi <strong>Pempek Tumpah di Pasar 16 Palembang</strong>, yang tak hanya lezat tetapi juga kaya nilai sejarah dan budaya. Siswa juga berkesempatan mencicipi hidangan khas Palembang lainnya, seperti pindang tekwan dan model dl.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Kegiatan ini mengajarkan siswa untuk menghargai warisan kuliner lokal dan memahami bahwa makanan dapat menjadi jendela untuk melihat kebudayaan suatu daerah.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Bagian tak terpisahkan dari perjalanan ini adalah kunjungan ke toko buku <strong>Gramedia World</strong>. Para siswa diberikan alokasi waktu untuk memilih dan membeli buku yang mereka minati. Kegiatan ini bertujuan untuk:</p><ol><li class=\"ql-align-justify\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Mendorong minat baca</strong> di tengah gempuran media digital.</li><li class=\"ql-align-justify\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Melatih pengelolaan uang</strong> untuk kebutuhan edukatif.</li><li class=\"ql-align-justify\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Mengenal beragam genre</strong> buku dan sumber pengetahuan.</li></ol><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Elemen baru yang paling menarik dari perjalanan kali ini adalah kunjungan ke <strong>Pabrik Penggilingan Padi</strong>. Di sana, siswa mendapatkan wawasan langsung tentang:</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\"><br></p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Kepala Sekolah <strong>Agi Gustiawan, S. Pd</strong> menyampaikan kebanggaannya atas kelancaran dan kesuksesan kegiatan ini. \"Kami melihat peningkatan signifikan dalam <strong>kemandirian, kemampuan adaptasi, dan pemahaman sosial</strong> siswa. Kegiatan <em>IU-Safar</em> ini bukan hanya rekreasi, tetapi investasi dalam membentuk karakter generasi muda yang cerdas, mandiri, dan melek literasi,\" tutupnya.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Kegiatan ini diharapkan dapat menjadi agenda rutin tahunan <strong>SMA IT Ishlahul Ummah</strong> sebagai model pembelajaran di luar kelas yang aplikatif dan menyenangkan.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">&nbsp;</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">n</p>', 'nSMA IT Ishlahul Ummah – baru-baru ini menyelesaikan sebuah proyek belajar yang unik dan edukatif : kegiatan IU-Safar  ke Kota Palembang. Kegitaan ini dir...', 'publish', 'post', '/uploads/2025/10/hallo-sahabat-shalih-shalihah-sma-it-ishum-sudah-pernah-mendengar-atau-mengikuti-kegiatan-iu-sa.webp', 1169, 4, '2025-10-30 16:57:10', 'IU Safar 2025 - SMA IT Ishlahul Ummah', '&nbsp;nSMA IT Ishlahul Ummah – baru-baru ini menyelesaikan sebuah proyek belajar yang unik dan edukatif : kegiatan IU-Safar  ke Kota Palembang. Kegita...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:56:53'),
  (256, 'Haflah dan Wisuda Qur\'an Angkatan IV : Menjadi Generasi Cinta Al-Qur\'an', 'haflah-dan-wisuda-quran-angkatan-iv-menjadi-generasi-cinta-al-quran', 'Haflah dan Wisuda Qur\'an Gaza Angkatan IV: Menjadi Generasi Cinta Al-Qur\'anrnrnAlhamdulillah, momen penuh keberkahan dan haru kembali hadir dalam acara Haflah dan Wisuda Qur\'an Gaza Angkatan IV yang berlangsung dengan khidmat dan penuh makna (6 Mei 2025) ❤️.rnrnAcara ini menjadi bentuk apresiasi atas perjuangan dan kesungguhan para santri dalam menghafal kalamullah. Di antaranya adalah ananda Gaza, yang telah menyelesaikan hafalan dengan baik. Semoga Allah senantiasa menjaga hafalannya dan menjadikannya pribadi yang senantiasa mengamalkan Al-Qur’an dalam kehidupan sehari-hari.rnrnAcara semakin bermakna dengan hadirnya Ust. Heri Sholeh, L.C, yang memberikan motivasi dan nasihat mendalam tentang pentingnya menjadikan Al-Qur’an sebagai pedoman hidup. Beliau mengingatkan bahwa Al-Qur’an bukan hanya untuk dihafal, tapi untuk dipahami, diamalkan, dan dijadikan cahaya penuntun dalam setiap langkah kehidupan.rnrnWisuda Qur’an ini bukanlah akhir dari perjalanan, melainkan awal dari komitmen panjang untuk terus bersama Al-Qur’an. Menjadi generasi cinta Al-Qur’an berarti terus memperbaiki diri, memperkuat hafalan, dan menjadikan Al-Qur’an sebagai dasar dalam bersikap dan bertindak.rnrnSemoga:rnrnSetiap huruf yang dihafal menjadi cahaya di dunia dan akhiratrnrnPara santri terus istiqomah dalam menjaga hafalanrnrnKita semua terinspirasi menjadi bagian dari generasi Qur’ani yang diridhai Allahrnrn&nbsp;rnrn---rnrn📌 #HafalanQuran #WisudaQuran #CintaAlQuranrnrn&nbsp;', 'Haflah dan Wisuda Qur\'an Gaza Angkatan IV: Menjadi Generasi Cinta Al-Qur\'anrnrnAlhamdulillah, momen penuh keberkahan dan haru kembali hadir dalam acara Haflah d...', 'publish', 'post', '/uploads/campus-robbani.webp', 1607, 4, '2025-07-08 09:37:17', 'Haflah dan Wisuda Qur\'an Angkatan IV : Menjadi Generasi Cinta Al-Qur\'an - SMA IT Ishlahul Ummah', 'Haflah dan Wisuda Qur\'an Gaza Angkatan IV: Menjadi Generasi Cinta Al-Qur\'anrnrnAlhamdulillah, momen penuh keberkahan dan haru kembali hadir dalam acar...', NULL, '2026-09-11 15:07:23', '2026-09-12 09:13:43'),
  (257, 'OUTING CLASS - Swimming Time', 'outing-class-swimming-time', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Outing Class Swimming Time: Keseruan di Air*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada tanggal 23 April 2025, siswa-siswa sekolah melaksanakan outing class swimming time yang sangat dinantikan. Kegiatan ini dibagi menjadi 2 sesi untuk memastikan keselamatan dan kenyamanan semua peserta.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Sesi 1: Siswa dan Guru Laki-Laki*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sesi pagi dimulai pukul 08.00 hingga 10.00 WIB, khusus untuk siswa dan guru laki-laki. Kegiatan ini sangat disambut baik oleh peserta, yang dapat menikmati waktu berenang dan bermain air bersama. Mereka dapat menunjukkan kemampuan renang mereka dan bermain permainan air yang menyenangkan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Sesi 2: Siswa dan Guru Perempuan*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sesi siang dimulai pukul 10.00 hingga 12.00 WIB. Kegiatan ini juga sangat dinantikan oleh peserta, yang dapat menikmati waktu berenang dan bermain air bersama. Mereka dapat menunjukkan kemampuan renang mereka dan bermain permainan air yang menyenangkan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Keseruan dan Manfaat*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan outing class swimming time ini tidak hanya memberikan kesempatan untuk berolahraga, tetapi juga untuk bersenang-senang dan melepas stres. Peserta dapat menikmati waktu bersama teman-teman dan meningkatkan keterampilan sosial mereka.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Kesimpulan*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Outing class swimming time pada tanggal 23 April 2025 merupakan kegiatan yang sangat sukses dan menyenangkan. Pembagian sesi pagi dan siang memastikan keselamatan dan kenyamanan semua peserta. Kegiatan ini dapat meningkatkan kesehatan fisik dan mental siswa, serta meningkatkan keterampilan sosial mereka.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3831\" src=\"/uploads/2025/04/img-20250424-wa0009-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3832\" src=\"/uploads/2025/04/feed-ig-terbaru-20250424-093832-0000-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"size-medium wp-image-3833\" src=\"/uploads/2025/04/img-20250423-132522-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"size-medium wp-image-3834\" src=\"/uploads/2025/04/img-20250423-132818-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3835\" src=\"/uploads/2025/04/img-20250423-wa0009-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3836\" src=\"/uploads/2025/04/img-20250423-wa0058-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3837\" src=\"/uploads/2025/04/img-20250424-wa0007-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p>n', '*Outing Class Swimming Time: Keseruan di Air*nPada tanggal 23 April 2025, siswa-siswa sekolah melaksanakan outing class swimming time yang sangat dinantikan. Ke...', 'publish', 'post', '/uploads/2025/04/2-20250430-114112-0001.webp', 875, 4, '2025-04-30 12:17:42', 'OUTING CLASS - Swimming Time - SMA IT Ishlahul Ummah', '*Outing Class Swimming Time: Keseruan di Air*nPada tanggal 23 April 2025, siswa-siswa sekolah melaksanakan outing class swimming time yang sangat dina...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (258, 'IU Berkhidmat', 'iu-berkhidmat', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, selama 1 pekan, siswa/i SMA IT Ishlahul Ummah telah melaksanakan program unggulan sekolah yaitu IU Berkhidmat (pengabdian masyarakat). Kegiatan ini berlangsung di 2 tempat berkhidmat, yaitu:</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">- Tempat Berkhidmat 1: Unit TK dan SD IT Ishlahul Ummah<br />n- Tempat Berkhidmat 2: 4 masjid, 2 TPA, dan 1 panti asuhan di Kota Prabumulih</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan IU Berkhidmat</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Siswa/i SMA IT Ishlahul Ummah telah melakukan berbagai kegiatan pengabdian masyarakat, seperti:</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">- Membantu kegiatan belajar mengajar di Unit TK dan SD IT Ishlahul Ummah<br />n- Mengajar anak-anak di TPA dan masjid<br />n- Membantu kegiatan sehari-hari di panti asuha<br />\nn- Mengikuti kegiatan keagamaan di masjid</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dampak Positif</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga kegiatan IU Berkhidmat ini memberikan dampak positif bagi:</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">- Diri pribadi siswa: meningkatkan kesadaran sosial, empati, dan keterampilan kepemimpina<br />\nn- Keluarga wali siswa: meningkatkan kesadaran akan pentingnya pendidikan dan pengabdian masyarakat<br />n- Sekolah: meningkatkan reputasi dan kualitas pendidika<br />\nn- Warga sekitar tempat pengabdian: meningkatkan kesadaran akan pentingnya pendidikan dan pengabdian masyarakat</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kesimpulan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">IU Berkhidmat merupakan program unggulan SMA IT Ishlahul Ummah yang sangat bermanfaat bagi siswa/i dan masyarakat. Kegiatan ini meningkatkan kesadaran sosial, empati, dan keterampilan kepemimpinan siswa/i, serta memberikan dampak positif bagi masyarakat sekitar. Semoga kegiatan ini dapat terus berlanjut dan memberikan manfaat yang lebih besar di masa depan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3779\" src=\"/uploads/2025/04/img-20250321-wa0016-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3780\" src=\"/uploads/2025/04/img-20250317-wa0033-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3781\" src=\"/uploads/2025/04/img-20250317-wa0053-300x135.webp\" alt=\"\" width=\"300\" height=\"135\" /> <img class=\"alignnone size-medium wp-image-3782\" src=\"/uploads/2025/04/img-20250317-wa0060-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3783\" src=\"/uploads/2025/04/img-20250317-wa0064-300x240.webp\" alt=\"\" width=\"300\" height=\"240\" /> <img class=\"alignnone size-medium wp-image-3784\" src=\"/uploads/2025/04/img-20250317-wa0078-300x213.webp\" alt=\"\" width=\"300\" height=\"213\" /> <img class=\"alignnone size-medium wp-image-3785\" src=\"/uploads/2025/04/img-20250317-wa0084-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3786\" src=\"/uploads/2025/04/img-20250317-wa0102-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3787\" src=\"/uploads/2025/04/img-20250318-wa0001-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3788\" src=\"/uploads/2025/04/img-20250318-wa0003-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3789\" src=\"/uploads/2025/04/img-20250318-wa0018-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3790\" src=\"/uploads/2025/04/img-20250318-wa0028-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3791\" src=\"/uploads/2025/04/img-20250318-wa0029-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3792\" src=\"/uploads/2025/04/img-20250318-wa0040-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3793\" src=\"/uploads/2025/04/img-20250318-wa0042-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3794\" src=\"/uploads/2025/04/img-20250318-wa0046-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3795\" src=\"/uploads/2025/04/img-20250318-wa0053-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3796\" src=\"/uploads/2025/04/img-20250319-wa0008-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3797\" src=\"/uploads/2025/04/img-20250319-wa0035-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3798\" src=\"/uploads/2025/04/img-20250319-wa0050-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3799\" src=\"/uploads/2025/04/img-20250319-wa0057-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3800\" src=\"/uploads/2025/04/img-20250319-wa0069-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3801\" src=\"/uploads/2025/04/img-20250320-wa0007-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3802\" src=\"/uploads/2025/04/img-20250320-wa0041-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3803\" src=\"/uploads/2025/04/img-20250320-wa0070-226x300.webp\" alt=\"\" width=\"226\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3804\" src=\"/uploads/2025/04/img-20250320-wa0078-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3805\" src=\"/uploads/2025/04/img-20250321-wa0008-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3806\" src=\"/uploads/2025/04/img-20250321-wa0010-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p>n', 'Alhamdulillah, selama 1 pekan, siswa/i SMA IT Ishlahul Ummah telah melaksanakan program unggulan sekolah yaitu IU Berkhidmat (pengabdian masyarakat). Kegiatan i...', 'publish', 'post', '/uploads/2025/04/3-20250406-085630-0002.webp', 1026, 4, '2025-04-07 13:44:29', 'IU Berkhidmat - SMA IT Ishlahul Ummah', 'Alhamdulillah, selama 1 pekan, siswa/i SMA IT Ishlahul Ummah telah melaksanakan program unggulan sekolah yaitu IU Berkhidmat (pengabdian masyarakat)....', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (259, 'Belajar Bersama Maestro 2025', 'belajar-bersama-maestro-2025', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Belajar Bersama Maestro atau dikenal dengan singkatan BBM yang merupakan salah satu program unggulan di tahun 2025 ini. Kegiatan ini mengajak wali murid untuk berpartisipasi langsung dalam memberikan wawasan keilmuan sesuai dengan profesi mereka masing-masing.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada tahun 2025, kita mendapatkan kesempatan untuk belajar dari wali murid yang berprofesi sebagai ketua Dapur Ishlahul Ummah. Ananda siswa/i kelas X, XI, dan XII semuanya terlibat dalam pembelajaran Bioteknologi Pangan membuat Roti.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan Pembelajaran</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan pembelajaran ini berlangsung dengan sangat antusias dan menyenangkan. Wali murid yang berprofesi sebagai ketua Dapur Ishlahul Ummah membimbing siswa/i dalam membuat roti dengan menggunakan teknologi bioteknologi pangan. Siswa/i belajar tentang proses pembuatan roti, mulai dari pemilihan bahan baku, pengolahan bahan, hingga proses fermentasi.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Materi yang Disampaikan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Wali murid menyampaikan materi tentang bioteknologi pangan dan aplikasinya dalam pembuatan roti. Siswa/i belajar tentang peran mikroorganisme dalam proses fermentasi, serta bagaimana teknologi bioteknologi pangan dapat meningkatkan kualitas dan kuantitas roti.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Keterlibatan Siswa/i</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Siswa/i kelas X, XI, dan XII semuanya terlibat dalam kegiatan pembelajaran ini. Mereka bekerja sama dalam tim untuk membuat roti dengan menggunakan teknologi bioteknologi pangan. Siswa/i juga belajar tentang pentingnya kerja sama tim dan komunikasi dalam proses pembuatan roti.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hasil Pembelajaran</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hasil pembelajaran ini sangat memuaskan. Siswa/i berhasil membuat roti yang lezat dan berkualitas dengan menggunakan teknologi bioteknologi pangan. Mereka juga memperoleh pengetahuan dan keterampilan baru tentang bioteknologi pangan dan aplikasinya dalam pembuatan roti.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kesimpulan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pembelajaran Bioteknologi Pangan membuat Roti dengan wali murid ketua Dapur Ishlahul Ummah merupakan kegiatan yang sangat bermanfaat dan menyenangkan. Siswa/i memperoleh pengetahuan dan keterampilan baru tentang bioteknologi pangan dan aplikasinya dalam pembuatan roti. Kegiatan ini juga meningkatkan kesadaran siswa/i tentang pentingnya teknologi bioteknologi pangan dalam meningkatkan kualitas dan kuantitas pangan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3772\" src=\"/uploads/2025/04/6-20250316-105052-0003-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3773\" src=\"/uploads/2025/04/9-20250315-095629-0007-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3774\" src=\"/uploads/2025/04/4-20250316-105052-0001-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3775\" src=\"/uploads/2025/04/5-20250316-105052-0002-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /></p>n', 'Belajar Bersama Maestro atau dikenal dengan singkatan BBM yang merupakan salah satu program unggulan di tahun 2025 ini. Kegiatan ini mengajak wali murid untuk b...', 'publish', 'post', '/uploads/2025/04/2-20250406-085630-0001.webp', 863, 4, '2025-04-07 12:43:36', 'Belajar Bersama Maestro 2025 - SMA IT Ishlahul Ummah', 'Belajar Bersama Maestro atau dikenal dengan singkatan BBM yang merupakan salah satu program unggulan di tahun 2025 ini. Kegiatan ini mengajak wali mur...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (260, 'Sanlat Ramadhan 1446 H', 'sanlat-ramadhan-1446-h', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sanlat Ramadhan 2025: Sebuah Perayaan Spiritual yang Mengharukan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sanlat Ramadhan 2025 telah dilaksanakan pada tanggal 13-14 Maret 2025. Kegiatan ini merupakan salah satu program yang sangat dinantikan oleh siswa-siswi sekolah, karena merupakan kesempatan untuk memperdalam ilmu agama dan meningkatkan kesadaran spiritual.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan Berjalan dengan Hikmat dan Lancar</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan Sanlat Ramadhan 2025 berjalan dengan hikmat dan lancar. Siswa-siswi sekolah sangat antusias dan bersemangat dalam mengikuti setiap kegiatan yang telah disiapkan. Dari shalat tarawih berjamaah hingga tausiyah yang disampaikan oleh ustadz-ustadz yang berkompeten.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Tausiyah dari Ustadz yang Berkompeten</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Tausiyah yang disampaikan oleh Ust. Zahyudi, M.HI dan Ust. Heri Soleh, LC sangat mengharukan dan memberikan kesan yang mendalam bagi siswa-siswi sekolah. Mereka membahas tentang pentingnya berpuasa, kesadaran spiritual, dan bagaimana meningkatkan kualitas iman dan taqwa.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Mabit dan Berbagi Takjil</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Selain tausiyah, kegiatan Mabit (Malam Bina Iman dan Taqwa) juga menjadi salah satu kegiatan yang sangat dinantikan. Siswa-siswi sekolah berkesempatan untuk bermalam di sekolah dan melakukan kegiatan spiritual lainnya. Berbagi takjil juga menjadi salah satu kegiatan yang sangat menyenangkan, di mana siswa-siswi sekolah dapat berbagi makanan dengan teman-teman yang lain.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kesimpulan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sanlat Ramadhan 2025 telah menjadi sebuah perayaan spiritual yang mengharukan dan memberikan kesan yang mendalam bagi siswa-siswi sekolah. Kegiatan ini telah berjalan dengan hikmat dan lancar, dan telah memberikan kesempatan bagi siswa-siswi sekolah untuk memperdalam ilmu agama dan meningkatkan kesadaran spiritual. Semoga kegiatan ini dapat menjadi inspirasi bagi siswa-siswi sekolah untuk meningkatkan kualitas iman dan taqwa mereka.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3767\" src=\"/uploads/2025/04/img-20250313-wa0070-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3766\" src=\"/uploads/2025/04/img-20250313-wa0046-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3761\" src=\"/uploads/2025/04/img-20250312-wa0051-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3760\" src=\"/uploads/2025/04/img-20250312-wa0033-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3759\" src=\"/uploads/2025/04/8-20250315-095628-0006-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3758\" src=\"/uploads/2025/04/6-20250315-095628-0004-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3763\" src=\"/uploads/2025/04/img-20250312-wa0059-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3762\" src=\"/uploads/2025/04/img-20250312-wa0057-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3764\" src=\"/uploads/2025/04/img-20250313-wa0003-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3765\" src=\"/uploads/2025/04/img-20250313-wa0031-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3752\" src=\"/uploads/2025/04/img-20250313-wa0093-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3756\" src=\"/uploads/2025/04/4-20250315-095628-0002-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3755\" src=\"/uploads/2025/04/3-20250315-095628-0001-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3754\" src=\"/uploads/2025/04/img-20250313-wa0128-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3753\" src=\"/uploads/2025/04/img-20250313-wa0104-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p>n', 'Sanlat Ramadhan 2025: Sebuah Perayaan Spiritual yang MengharukannSanlat Ramadhan 2025 telah dilaksanakan pada tanggal 13-14 Maret 2025. Kegiatan ini merupakan s...', 'publish', 'post', '/uploads/2025/04/1-20250406-085630-0000.webp', 253, 4, '2025-04-07 12:29:08', 'Sanlat Ramadhan 1446 H - SMA IT Ishlahul Ummah', 'Sanlat Ramadhan 2025: Sebuah Perayaan Spiritual yang MengharukannSanlat Ramadhan 2025 telah dilaksanakan pada tanggal 13-14 Maret 2025. Kegiatan ini m...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (261, 'Sumatif Akhir Semester Genap Tahun Pelajaran 2024-2025', 'sumatif-akhir-semester-genap-tahun-pelajaran-2024-2025', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SAS Genap Kelas 12 Tahun Pelajaran 2024/2025: Sebuah Langkah Menuju Kesuksesan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SAS (Sumatif Akhir Semester) genap kelas 12 tahun pelajaran 2024/2025 telah dilaksanakan pada tanggal 12-19 Maret 2025. Bagi siswa kelas 12, SAS genap merupakan salah satu ujian yang sangat penting untuk menentukan kelulusan dan masa depan mereka. Pelaksanaan SAS genap ini merupakan langkah penting dalam mengevaluasi kemampuan dan pengetahuan siswa setelah satu semester penuh belajar.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Persiapan dan Pelaksanaan SAS Genap</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Persiapan SAS genap kelas 12 tahun pelajaran 2024/2025 telah dimulai sejak beberapa minggu sebelum pelaksanaan ujian. Siswa kelas 12 telah mempersiapkan diri dengan belajar secara intensif dan mengerjakan soal-soal latihan untuk meningkatkan kemampuan dan kecepatan dalam mengerjakan soal.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pelaksanaan SAS genap kelas 12 tahun pelajaran 2024/2025 telah berlangsung selama 7 hari, dari tanggal 12-19 Maret 2025. Selama pelaksanaan ujian, siswa kelas 12 telah menunjukkan semangat dan kesungguhan dalam mengerjakan soal-soal yang diberikan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hasil SAS Genap</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hasil SAS genap kelas 12 tahun pelajaran 2024/2025 akan diumumkan setelah pelaksanaan ujian. Hasil ini akan menentukan kelulusan siswa kelas 12.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SAS genap kelas 12 tahun pelajaran 2024/2025 telah dilaksanakan dengan sukses dan lancar. Pelaksanaan ujian ini merupakan langkah penting dalam mengevaluasi kemampuan dan pengetahuan siswa setelah satu semester penuh belajar.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3748\" src=\"/uploads/2025/04/1-20250312-174823-0000-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'SAS Genap Kelas 12 Tahun Pelajaran 2024/2025: Sebuah Langkah Menuju KesuksesannSAS (Sumatif Akhir Semester) genap kelas 12 tahun pelajaran 2024/2025 telah dilak...', 'publish', 'post', '/uploads/2025/04/4-20250406-085630-0003.webp', 1816, 4, '2025-04-07 08:37:46', 'Sumatif Akhir Semester Genap Tahun Pelajaran 2024-2025 - SMA IT Ishlahul Ummah', 'SAS Genap Kelas 12 Tahun Pelajaran 2024/2025: Sebuah Langkah Menuju KesuksesannSAS (Sumatif Akhir Semester) genap kelas 12 tahun pelajaran 2024/2025 t...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (262, 'Tarhib Ramadhan Ishlahul Ummah', 'tarhib-ramadhan-ishlahul-ummah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">TARHIB RAMADHAN ISHLAHUL UMMAH</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kasih untuk Palestina</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">bersama Syekh Ma\'mun MA Abu Samrah LC., M.Ag.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">diinisiasi oleh UPZ Ishlahul Ummah x LMI Zakat</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Jum\'at, 21 Februari 2025</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, Kegiatan Tarhib Ramadhan Yayasan Ishlahul Ummah berjalan lancar. adapun rangkaian kegiatan ini diawali dengan pembiasaan pagi dzikir pagi dan sholat dhuha. Kemudian dilanjutkan dengan dongeng Ramadhan bersama Kak Andi Kampung Dongeng Sumsel untuk TK dan SD. Sedangkan SD materi BPI dengan tema \"Ramadhan Terbaikku\". Adapun materi Palestina diisi langsung oleh Syekh Ma\'mun, Lc., M.Ag.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada kegiatan ini juga ada persembahan spesial dari SMAIT Ishlahul Ummah Prabumulih yaitu <em>launching </em>Buku Hujan Bintang di Langit Gaza Karya Guru dan Siswa/i SMAIT Ishlahul Ummah dan <em>launching</em> program rutin UPZ Ishlahul Ummah Prabumulih yaitu \"WAKTU\" (wakaf dua ribu untuk palestinaku)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kasih Cinta untuk Palestina</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3732\" src=\"/uploads/2025/02/img-20250221-wa0009-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3733\" src=\"/uploads/2025/02/img-20250221-wa0049-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3734\" src=\"/uploads/2025/02/img-20250221-wa0056-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3735\" src=\"/uploads/2025/02/img-20250221-wa0089-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3736\" src=\"/uploads/2025/02/img-20250221-wa0101-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'TARHIB RAMADHAN ISHLAHUL UMMAHnKasih untuk Palestinanbersama Syekh Ma\'mun MA Abu Samrah LC., M.Ag.ndiinisiasi oleh UPZ Ishlahul Ummah x LMI ZakatnJum\'at, 21 Feb...', 'publish', 'post', '/uploads/2025/02/2-20250224-114629-0001.webp', 1774, 4, '2025-02-24 13:39:59', 'Tarhib Ramadhan Ishlahul Ummah - SMA IT Ishlahul Ummah', 'TARHIB RAMADHAN ISHLAHUL UMMAHnKasih untuk Palestinanbersama Syekh Ma\'mun MA Abu Samrah LC., M.Ag.ndiinisiasi oleh UPZ Ishlahul Ummah x LMI ZakatnJum\'...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (263, 'Munaqosah TTQ Kelas Akhir 2025', 'munaqosah-ttq-kelas-akhir-2025', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah pada tanggal 19 - 20 Februari 2025 telah dilaksanakan Munaqosah TTQ Kelas Akhir TP.2024-2025.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini dibuka oleh Kepala Rumah Qur an namun diwakilkan oleh Sekretaris Rumah Qur an Ishlahul Ummah yaitu Ustdzah Salma Najibah, S.Pd. Ustadzah Salma berpesan kepada semua yang menjadi peserta ujian munaqosah <em>\"bahwa apapun yang terjadi saat munaqoah terima takdir itu, cintai takdir itu karena yang menakdirkan adalah yang mencintai Kita\".</em></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan munaqosah dilaksanakan selama dua hari, pada hari kedua ditutup dengan motivasi dalam menghafal Qur an oleh salah satu Dewan juri Munaqosah TTQ Kelas Akhir tahun ini.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun juri munaqosah TTQ Kelas Akhir TP. 2024-2025 diantaranya Ustdzah Sri Kurnia, S.H, Ustdzah Salma Najibah, S.Pd, Ustdzah Ela Puspita Sari, S.E dan Ustdzah Okta Heriyani, S.E.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Yang menjadi peserta munaqosah adalah seluruh siswa/i kelas XII yakni :</p><ol><li>M. Abi Khatim Al Habsy Lubis (6,5 juz)</li><li>Alief Rasya Arrafi (6,5 juz)</li><li>Alifia Kirana Putri (4 juz)</li><li>Nadia Shakila (4 juz)</li><li>Katrinajah Sabilillah (4 juz)</li><li>Alfa Reza Angga Saputra (3 juz)</li><li>M. Naufal Rohmattullah (1 juz)</li><li>Toby Aldinata Timothy (1 juz)</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini berlangsung dengan lancar dan khidmat. semua ini tidak terlepas dari semua stakeholder ustadz/ustdzah semuanya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3710\" src=\"/uploads/2025/02/img-20250219-wa0172-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3711\" src=\"/uploads/2025/02/img-20250219-wa0209-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3709\" src=\"/uploads/2025/02/img-20250219-wa0170-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3706\" src=\"/uploads/2025/02/img-20250219-wa0154-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3722\" src=\"/uploads/2025/02/img-20250220-wa0035-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3723\" src=\"/uploads/2025/02/img-20250220-wa0040-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3724\" src=\"/uploads/2025/02/img-20250224-wa0020-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3704\" src=\"/uploads/2025/02/img-20250219-wa0130-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3703\" src=\"/uploads/2025/02/img-20250219-wa0114-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3702\" src=\"/uploads/2025/02/img-20250219-wa0092-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3695\" src=\"/uploads/2025/02/img-20250219-wa0046-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3697\" src=\"/uploads/2025/02/img-20250219-wa0069-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3699\" src=\"/uploads/2025/02/img-20250219-wa0086-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3698\" src=\"/uploads/2025/02/img-20250219-wa0082-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3712\" src=\"/uploads/2025/02/img-20250220-wa0068-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3713\" src=\"/uploads/2025/02/img-20250220-wa0071-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3714\" src=\"/uploads/2025/02/img-20250220-wa0073-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3718\" src=\"/uploads/2025/02/img-20250220-wa0089-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3717\" src=\"/uploads/2025/02/img-20250220-wa0079-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3716\" src=\"/uploads/2025/02/img-20250220-wa0077-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3721\" src=\"/uploads/2025/02/img-20250220-wa0126-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3719\" src=\"/uploads/2025/02/img-20250220-wa0091-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'Alhamdulillah pada tanggal 19 - 20 Februari 2025 telah dilaksanakan Munaqosah TTQ Kelas Akhir TP.2024-2025.nKegiatan ini dibuka oleh Kepala Rumah Qur an namun d...', 'publish', 'post', '/uploads/2025/02/2-20250224-100013-0001.webp', 1484, 4, '2025-02-24 11:29:49', 'Munaqosah TTQ Kelas Akhir 2025 - SMA IT Ishlahul Ummah', 'Alhamdulillah pada tanggal 19 - 20 Februari 2025 telah dilaksanakan Munaqosah TTQ Kelas Akhir TP.2024-2025.nKegiatan ini dibuka oleh Kepala Rumah Qur...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (264, 'HIT GENIUS Berlangsung 3 Hari, Berjalan Lancar dan Meriah', 'hit-genius-berlangsung-3-hari-berjalan-lancar-dan-meriah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Acara HIT GENIUS yang berlangsung selama 3 hari, dari tanggal 21 sampai dengan 23 Januari 2025, telah berjalan dengan lancar dan meriah. acara ini diikuti oleh kurang lebih 229 peserta lomba.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>Acara Pembukaan yang Meriah</strong></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Acara pembukaan HIT Genius diawali dengan sambutan dari Bapak Drs. M. Hosarudin, M.M. yang menyambut hangat para peserta dan memaparkan tujuan acara ini. Kemudian, acara dilanjutkan dengan perlombaan COC, mewarnai kaligrafi dan MHQ dihari pertama.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hari ke-2 berlanjut dengan lomba Badminton, hafalan surat pendek, melukis sketsa, dan Da\'i/Da\'iyah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hari ke-3 lomba badminton (final) dan LTBB tingkat SMA. selama berlangsungnya kegiatan HIT Genius, banyak juga peserta stand bazar yang ikut serta memeriahkan kegiatan ini dengan menjual aneka macam jajanan ringan maupun berat, serta jasa dan produk barang.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>Suasana yang Meriah</strong></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">selama acara berlangsung, suasana yang meriah dan kompetitif dapat dirasakan. Para peserta sangat antusias dan bersemangat dalam mengikuti lomba - lomba yang diselenggarakan. penonton juga sangat antusias dan memberikan dukungan kepada para peserta.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">dihari ke-3 setelah selesai perlombaan berlanjut kegiatan penutupan kegiatan disertai dengan pengumuman juara lomba. Kegiatan HIT Genius ditutup oleh Ust. H. Mat Amin, S.Ag.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah Kegiata HIT GENIUS berjalan lancar. semua ini tidak akan bisa terwujud kecuali karena pertolongan Allah swt melalui perantara sponsor, panitia, juri semua <em>stakeholder</em> yang terlibat dalam kegiatan ini.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3673\" src=\"/uploads/2025/01/1-20250121-151144-0000-1-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3674\" src=\"/uploads/2025/01/1-20250122-220730-0000-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3678\" src=\"/uploads/2025/01/1-20250124-121059-0000-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3679\" src=\"/uploads/2025/01/2-20250122-220730-0001-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3681\" src=\"/uploads/2025/01/4-20250122-220730-0003-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3684\" src=\"/uploads/2025/01/4-20250121-151145-0003-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3683\" src=\"/uploads/2025/01/2-20250124-121100-0001-240x300.webp\" alt=\"\" width=\"240\" height=\"300\" /></p>n', 'Acara HIT GENIUS yang berlangsung selama 3 hari, dari tanggal 21 sampai dengan 23 Januari 2025, telah berjalan dengan lancar dan meriah. acara ini diikuti oleh...', 'publish', 'post', '/uploads/2025/01/banner-utama-hit-genius-20250114-121330-0000.webp', 767, 4, '2025-01-31 10:10:26', 'HIT GENIUS Berlangsung 3 Hari, Berjalan Lancar dan Meriah - SMA IT Ishlahul Ummah', 'Acara HIT GENIUS yang berlangsung selama 3 hari, dari tanggal 21 sampai dengan 23 Januari 2025, telah berjalan dengan lancar dan meriah. acara ini dii...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (265, 'RAPAT KOMITE DAN PEMBAGIAN HASIL BELAJAR SEMESTER GANJIL 2024-2025', 'rapat-komite-dan-pembagian-hasil-belajar-semester-ganjil-2024-2025', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Prabmulih, Jum\'at, 13 November 2024 – Acara Rapat komite dan  pembagian hasil belajar semester ganjil TP. 2024-2025 di SMA IT Ishlahul Ummah menjadi ajang yang tepat bagi orang tua siswa untuk berinteraksi langsung dengan guru. Selain menerima rapor, orang tua juga berkesempatan untuk berdiskusi mengenai perkembangan anak mereka. suasana hangat dan kekeluargaan tercipta di antara semua yang hadir.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3647\" src=\"/uploads/2024/12/whatsapp-image-2024-12-19-at-112149-3-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3648\" src=\"/uploads/2024/12/whatsapp-image-2024-12-19-at-112149-2-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3649\" src=\"/uploads/2024/12/whatsapp-image-2024-12-19-at-112149-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3650\" src=\"/uploads/2024/12/whatsapp-image-2024-12-19-at-112149-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'Prabmulih, Jum\'at, 13 November 2024 – Acara Rapat komite dan  pembagian hasil belajar semester ganjil TP. 2024-2025 di SMA IT Ishlahul Ummah menjadi ajang yang...', 'publish', 'post', '/uploads/2024/12/whatsapp-image-2024-12-19-at-112129-scaled.webp', 1626, 4, '2024-12-19 11:38:31', 'RAPAT KOMITE DAN PEMBAGIAN HASIL BELAJAR SEMESTER GANJIL 2024-2025 - SMA IT Ishlahul Ummah', 'Prabmulih, Jum\'at, 13 November 2024 – Acara Rapat komite dan  pembagian hasil belajar semester ganjil TP. 2024-2025 di SMA IT Ishlahul Ummah menjadi a...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (266, 'PERKEMAHAN DAN PELANTIKAN BANTARA DAN LAKSANA', 'perkemahan-dan-pelantikan-bantara-dan-laksana', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">PRABUMULIH.- Baru - baru ini SMA IT Ishlahul Ummah melaksanakan kegiatan Perkemahan Pelantikan pengurus Bantara dan Laksana Pramuka Ambalan Umar Bin Khattab dan Nisaibah Binti Ka\'ab di lapangan Sekolah yang dihadiri langsung oleh Kepala Sekolah, Kwarran Pali, DKC dan DKR</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan tersebut dibuka langsung oleh kak Andi. Beliau memberikan pesan kepada calon Bantara dan laksana agar mampu membantu adik kelasnya menjadi siswa yang lebih teratur dalam melaksanakan kegiatan sekolah, beliau juga menyampaikan bahwa dengan adanya kegiatan tersebut bisa menjadikan kakak Bantara dan Laksana yang mampu bertanggung jawab serta mendorong untuk memberikan contoh yang baik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3633\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-102757-2-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3634\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-102526-2-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3635\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-102526-1-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3636\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-102753-2-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3637\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-102753-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone 