  (268, 'SAS Ganjil TP. 2024-2025', 'sas-ganjil-tp-2024-2025', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT Ishlahul Ummah telah melaksanakan kegiatan Sumatif Akhir Semester Ganil Tahun Pelajaran 2024-2025. Kegiatan ini bertujuan untuk mengukur kemampuan dan pemahaman siswa terhadap materi yang telah disampaikan selama semester ganjil. Seluruh siswa mengikuti kegiatan ini dengan antusias selama satu pekan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3613\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-113706-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3614\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-113707-1-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3615\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-113707-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p>n', 'SMA IT Ishlahul Ummah telah melaksanakan kegiatan Sumatif Akhir Semester Ganil Tahun Pelajaran 2024-2025. Kegiatan ini bertujuan untuk mengukur kemampuan dan pe...', 'publish', 'post', '/uploads/2024/12/8.webp', 1319, 4, '2024-12-19 10:47:12', 'SAS Ganjil TP. 2024-2025 - SMA IT Ishlahul Ummah', 'SMA IT Ishlahul Ummah telah melaksanakan kegiatan Sumatif Akhir Semester Ganil Tahun Pelajaran 2024-2025. Kegiatan ini bertujuan untuk mengukur kemamp...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (269, 'Pelatihan dan Sertifikasi Content Creator dan Social Media Marketing', 'pelatihan-dan-sertifikasi-content-creator-dan-social-media-marketing', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Palembang, 23-24 November 2024</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah siswa dan guru SMA IT Ishlahul Ummah mendapatkan kesempatan mengikuti pelatihan dan sertifikasi <em>content creator</em> dan <em>Social media marketing</em> selama dua hari.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada hari pertama, siswa dan guru diberikan materi tentang Bank Sentral dan Cinta Bangga Paham Rupiah oleh Bank Indonesia. Kemudian dilanjutkan dengan materi tentang content creator dan social media marketing oleh Media Institue Indonesia.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">siswa dan guru diwajibkan menyelesaikan tugas membuat content yang kemudian di presentasikan didepan Asesor dihari ke-dua.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan pelatihan dan sertifikasi ini diselenggarakan oleh Bank Indonesia dan Kampung Dongeng Sumatera Selatan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3603\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-102959-1-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3605\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-103001-1-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3606\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17