  (271, 'Kajian Buku', 'kajian-buku', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT Ishlahul Ummah Prabumulih memiliki salah satu program yang dapat mendukung peningkatan literasi anak Indonesia yaitu Kajian Buku. Tujuan dari adanya kajian buku adalah untuk membiasakan anak-anak senang terhadap buku sehingga menmbuhkan kecintaan terhadap ilmu.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kajian buku adalah salah sat rangkaian lanjutan dari program Safar ke Palembang, pada saat safar siswa diwajibkan untuk membeli buku dengan tema yang telah ditentukan untuk tiap tingkatan. Kemudian siswa menyelesaikan membaca buku yang telah dibeli dan dilanjutkan dengan presentasi kajian buk yang memuat informasi terkait buku yang telah dibaca didepan semua peserta didik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3580\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-100454-169x300.webp\" alt=\"\" width=\"169\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3581\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-100548-3-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3582\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-100548-2-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3583\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-100548-1-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3584\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-100548-300x224.webp\" alt=\"\" width=\"300\" height=\"224\" /></p>n', 'SMA IT Ishlahul Ummah Prabumulih memiliki salah satu program yang dapat mendukung peningkatan literasi anak Indonesia yaitu Kajian Buku. Tujuan dari adanya kaji...', 'publish', 'post', '/uploads/2024/12/3.webp', 718, 4, '2024-12-19 09:56:34', 'Kajian Buku - SMA IT Ishlahul Ummah', 'SMA IT Ishlahul Ummah Prabumulih memiliki salah satu program yang dapat mendukung peningkatan literasi anak Indonesia yaitu Kajian Buku. Tujuan dari a...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (272, 'Musyawarah Besar Organisasi', 'musyawarah-besar-organisasi', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Musyawarah besar organisasi merupakan proses demokrasi penting untuk mencapai keputusan bersama dan memajukan organisasi.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Melalui musyawarah, anggota organisasi dapat berdiskusi secara terbuka, membagikan pendapat dan mencapai kesepakatan. Proses ini memperkuat kepercayaan, meningkatkan kesadaran bersama dan membangun visi serta misi organisasi. Dengan demikian, musyawarah besar menjadi kunci keberhasilan dan kemajuan bersama, memungkinkan organisasi mencapai tujuan dan membangun kekuatan bersama.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3568\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094013-6-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3569\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094013-5-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3570\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094013-4-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3571\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094013-3-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3572\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094013-2-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3573\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094013-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3574\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094012-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3575\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-094011-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3576\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-093755-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'Musyawarah besar organisasi merupakan proses demokrasi penting untuk mencapai keputusan bersama dan memajukan organisasi.nMelalui musyawarah, anggota organisasi...', 'publish', 'post', '/uploads/2024/12/2.webp', 874, 4, '2024-12-19 09:13:34', 'Musyawarah Besar Organisasi - SMA IT Ishlahul Ummah', 'Musyawarah besar organisasi merupakan proses demokrasi penting untuk mencapai keputusan bersama dan memajukan organisasi.nMelalui musyawarah, anggota...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (273, 'SUARA DEMOKRASI', 'suara-demokrasi', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Prabumulih, 25 Oktober 2024</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pemilihan Ketua dan Wakil Ketua Osis merupakan momen penting dalam kehidupan siswa SMA IT Ishlahul Ummah. Pemilihan ini tidak hanya memilih pemimpin, tetapi jga memperkuat semangat demokrasi dan kesadaran berpartisipasi dikalangan siswa. Pada tanggal 25 Oktober 2024, siswa SMA IT Ishlahul Ummah memilih Ketua dan Wakil Ketua Osis baru SMA IT Ishlahul Ummah dengan penuh antusiasme.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pemilihan ketua dan wakil ketua OSIS berlangsung secara demokratis dan transparan. Panitia pemilihan, yang terdiri dari guru dan siswa, memastikan prosesnya berjalan adil dan tertib. calon ketua dan wakil ketua OSIS mempresentasikan visi dan misi mereka, diikuti debat dan tanya jawab dengan siswa.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Setelah proses kampanye, siswa memasuki ruang pemungutan suara untuk memilih calon pemimpin mereka kedepan. Suasana pemilihan berlangsung tenang dan tertib, dengan pengawasan ketat dari panitia.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Terdapat dua kandidat calon ketua dan wakil ketua OSIS yang bersaing dalam pemilihan ini yakni kandidat pasangan nomor urut satu yaitu M. Faiz Arrahman dan Muhammad Syarahil, sedangkan kandidat nomor urut dua yaitu M. Satria Wibawa dan Arsyil Ammarvallent Sulthanik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">setelah pemungutan suara selesai, panitia menghitung suara dan mengumumkan hasilnya. M. Satria Wibawa dan Arsyil Ammarvallent Sulthanik terpilih sebagai ketua dan wakil ketua OSIS baru SMA IT Ishlahul Ummah Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kepala sekolah SMA IT Ishlahul Ummah, Ustdzah Anita Carlyna, S.IP., M.Pd, menyambut baik proses pemilihan yang demokratis dan transparan. \"Pemilihan ini membuktikan bahwa siswa kita memiliki kesadaran demokrasi yang tinggi dan mamp memilih pemimpin yang tepat.\"</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pemilihan ketua dan wakil ketua OSIS SMA IT Ishlahul Ummah berhasil menunjukkan semangat demokrasi dan partisipasi siswa. Hasilnya diharapkan dapat membawa perubahan positif bagi sekolah dan siswa. Baarakallah wa Innalillah kepada M. Satria Wibawa dan Arsyil Ammarvallent Sulthanik sebagai ketua dan wakil ketua OSIS yang baru!</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3558\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091711-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3559\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091750-3-copy-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3560\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091750-2-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3561\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091750-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3562\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091750-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3563\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091749-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3564\" src=\"/uploads/2024/12/whatsapp-image-2024-12-17-at-091711-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p>n', 'Prabumulih, 25 Oktober 2024nPemilihan Ketua dan Wakil Ketua Osis merupakan momen penting dalam kehidupan siswa SMA IT Ishlahul Ummah. Pemilihan ini tidak hanya...', 'publish', 'post', '/uploads/2024/12/1.webp', 327, 4, '2024-12-19 08:51:58', 'SUARA DEMOKRASI - SMA IT Ishlahul Ummah', 'Prabumulih, 25 Oktober 2024nPemilihan Ketua dan Wakil Ketua Osis merupakan momen penting dalam kehidupan siswa SMA IT Ishlahul Ummah. Pemilihan ini ti...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (274, 'Belajar Mengenal Transportasi Umum - IU SAFAR ke Palembang', 'belajar-mengenal-transportasi-umum-iu-safar-ke-palembang', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Program Unggulan SMAIT Ishlahul Ummah yakni IU Safar yang telah dilaksanakan pada hari Rabu, 16 Oktober 2024. Kali ini mereka belajar mengenal transportasi umum yang ada di kota Palembang. sebelum pelaksanaan IU Safar, mereka telah mempersiapkan perencanaan ketika berada di Palembang mulai dari menentukan alat transportasi yang akan digunakan sampai budgeting selama melakukan safar.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pelajaran apa yang mereka dapatkan selama SAFAR ?</p><ol><li>Pemahaman Transportasi Umum yang ada di Palembang; dengan melakukan perjalanan dari satu tujuan ke tujuan yang lainnya saat di Palembang, murid belajar transportasi apa yang bisa digunakan ketika akan ke Gramedia dari Perpustakaan Daerah.</li><li>Manajemen Waktu; peserta didik belajar agar disipilin terhadap waktu. salah satunya mereka berangkat ke Palembang dari Prabumulih dengan Transportasi umum yakni DAMRI pukul 06.00 sudah berangkat. sehingga mereka harus berangkat sebelum pukul 06.00 agar tidak tertinggal.</li><li>Keterampilan bertanggung jawab; dengan melakukan perjalanan seharian bersama, murid belajar tentang tanggung jawab terhadap peran yang sudah mereka bagi seperti ketua, dokumentasi.</li><li>Kerjasama Tim; saat Safar mereka telah dibagi menjadi beberapa kelompok, sehingga saat diperjalanan mengajarkan murid tentang kerjasama, komunikasi dan pentingnya berkolaborasi dalam mencapai tujuan bersama.</li><li><em>Public Speaking ; </em>selama diperjalanan, mereka selalu berkomunikasi didalalam kelompok dan juga dengan masyarakat umum saat mereka tidak tahu mengenai rute dan alat transportasi apa yang harus digunakan.</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">selain dari 4 poin diatas, pelajaran yang didapatkan murid lainnya yaitu memunculkan empati satu sama lain baik dengan kelompok yakni tidak meninggalkan satu sama lain maupun masyarakat umum.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3479\" src=\"/uploads/2024/10/img-20241016-wa0005-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3480\" src=\"/uploads/2024/10/img-20241016-wa0038-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3481\" src=\"/uploads/2024/10/img-20241016-wa0048-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3482\" src=\"/uploads/2024/10/img-20241016-wa0067-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3483\" src=\"/uploads/2024/10/img-20241016-wa0072-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3485\" src=\"/uploads/2024/10/img-20241016-wa0080-1-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3486\" src=\"/uploads/2024/10/img-20241016-wa0083-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-ima