  (275, 'Mewujudkan Lingkungan Sekolah Sehat', 'mewujudkan-lingkungan-sekolah-sehat', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">dalam rangka mewujudkan Lingkungan Sekolah Sehat, SMAIT Ishlahul Ummah berupaya untuk membangun UKS 3T (Tanggap Tangkas Tangguh).</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMAIT Ishlahul Ummah sangat berterima kasih kepada semua pihak yang telah mendukung program sekolah terkhusus RS AR Bunda Prabumulih dan <em>Nugraha Dental Care.</em></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">dalam hal ini RS Ar Bunda Prabumulih memberikan bantuan berupa sarana kesehatan yaitu Ranjang (tempat tidur).</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><em>Nugraha Dental Care</em> juga memberikan donasi pendukung seperti Timbangan, lemari untuk alat kesehatan, termometer, seprei uks dan sebagainya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">semoga donasi yang diberikan berkah dan bermanfaat untuk generasi Tanggap, Tangkas dan Tangguh SMAIT Ishlahul Ummah</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3473\" src=\"/uploads/2024/10/img-20241014-wa0005-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3474\" src=\"/uploads/2024/10/img-20241014-wa0008-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3475\" src=\"/uploads/2024/10/img-20241014-wa0009-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3476\" src=\"/uploads/2024/10/img-20241014-wa0013-1-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p>n',