  (276, 'Sarasehan Kepala Sekolah SIT se-Sumatera Selatan', 'sarasehan-kepala-sekolah-sit-se-sumatera-selatan', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Minggu, 22 September 2024 -Hotel Azza Palembang</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sarasehan Kepala Sekolah SIT se-Sumsel JSIT Indonesia Wilayah Sumatera Selatan membangun sinergi SIT bermutu untuk Sumsel maju</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamduillah, dengan mengikuti kegiatan sarasehan sebagai penguatan kepala sekolah untuk meningkatkan mutu pendidikan sebagai kontribusi kita memajukan Sumsel khususnya Kota Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3468\" src=\"/uploads/2024/10/img-20240922-wa0006-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3469\" src=\"/uploads/2024/10/img-20240922-wa0008-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p>n', 'Minggu, 22 September 2024 -Hotel Azza PalembangnSarasehan Kepala Sekolah SIT se-Sumsel JSIT Indonesia Wilayah Sumatera Selatan membangun sinergi SIT bermutu unt...', 'publish', 'post', '/uploads/2024/10/img-20241020-wa0004-scaled.webp', 1683, 4, '2024-10-20 06:44:53', 'Sarasehan Kepala Sekolah SIT se-Sumatera Selatan - SMA IT Ishlahul Ummah', 'Minggu, 22 September 2024 -Hotel Azza PalembangnSarasehan Kepala Sekolah SIT se-Sumsel JSIT Indonesia Wilayah Sumatera Selatan membangun sinergi SIT b...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (277, 'Peningkatan Kapasitas Pembina dan Pengelolaan BPI', 'peningkatan-kapasitas-pembina-dan-pengelolaan-bpi', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sabtu-Minggu, 21-22 September 2024</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Para Kepala Sekolah serta PJ BPI SIT Ishlahul Ummah ikut serta dalam kegiatan \"Peningkatan Kapasitas Pembina dan Pengelolaan BPI\" yang diselenggarakan oleh JSIT Indonesia Wilayah Sumatera Selatan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3465\" src=\"/uploads/2024/10/img-20240922-wa0005-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'Sabtu-Minggu, 21-22 September 2024nPara Kepala Sekolah serta PJ BPI SIT Ishlahul Ummah ikut serta dalam kegiatan \"Peningkatan Kapasitas Pembina dan Pengelolaan...', 'publish', 'post', '/uploads/2024/10/img-20241020-wa0005-scaled.webp', 1801, 4, '2024-10-20 06:39:40', 'Peningkatan Kapasitas Pembina dan Pengelolaan BPI - SMA IT Ishlahul Ummah', 'Sabtu-Minggu, 21-22 September 2024nPara Kepala Sekolah serta PJ BPI SIT Ishlahul Ummah ikut serta dalam kegiatan \"Peningkatan Kapasitas Pembina dan Pe...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (278, 'Teman BBQ', 'teman-bbq', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Teman Belajar Berqurban (BBQ) adalah salah satu program upz Ishum yang mengajarkan untuk berbagi dengan menabung setiap bulannya di upz. Teman BBQ dilaksanakan dari unit TK sampai dengan SMA.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3461\" src=\"/uploads/2024/10/img-20240919-wa0016-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3462\" src=\"/uploads/2024/10/img-20240919-wa0017-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'Teman Belajar Berqurban (BBQ) adalah salah satu program upz Ishum yang mengajarkan untuk berbagi dengan menabung setiap bulannya di upz. Teman BBQ dilaksanakan...', 'publish', 'post', '/uploads/2024/10/img-20241020-wa0007-scaled.webp', 1812, 4, '2024-10-20 06:35:30', 'Teman BBQ - SMA IT Ishlahul Ummah', 'Teman Belajar Berqurban (BBQ) adalah salah satu program upz Ishum yang mengajarkan untuk berbagi dengan menabung setiap bulannya di upz. Teman BBQ dil...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (279, 'Perkemahan Penerimaan Tamu Ambalan', 'perkemahan-penerimaan-tamu-ambalan', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Perkemahan Penerimaan Tamu Ambalan telah dilaksanakan hari Jum\'at-Sabtu, 13-14 September 2024.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">dengan mengusung tema \"Menjadikan Jiwa Kepemimpinan sebagai Karakteristik bagi Tunas Muda yang Tanggap, Tangkas dan Tangguh serta Bermanfaat\"</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan berlangsung dengan lancar. pada hari sabtu pagi, kegiatan diawali dengan membangun tenda perkemahan bersama. Kemudian, dilanjutkan dengan lomba Bakiak dan Pionering tandu.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan perkemahan resmi dibuka dan ditutup oleh Kamabigus SMAIT Ishlahul Ummah yakni Kakak Anita Carlyn, S.IP., M.Pd. pada saat pembukaan Kakak Anita berpesan untuk \"mewujudkan jiwa Korsa, menyatukan upaya membangun Generasi Tanggap, Tangkas serta Tangguh menuju Indonesia Emas\"</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Saat malam Upacara Penyematan Api Unggun, Kakak Taftazani, S.Pd., M.M (Ka. Kwarcab Kota Prabumulih mengingatkan kembali bahwasanya \"Dasa Dharma Pramuka bukan hanya pandai diucapkan, tetapi ketika Adik-adik bisa menata Dasa Dharma 1 sampai dengan 9 dan 10 adalah kuncinya (suci dalam pikiran, perkataan dan perbuatan), maka kalian akan menjadi orang yang bak insyaallah\"</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">\"Orang yang baik itu ketika dia berbuat salah dia akan memperbaiki dirinya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan akhir dari perkemahan ini adalah Hiking sebagai penutupnya</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3443\" src=\"/uploads/2024/10/img-20240915-wa0038-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3444\" src=\"/uploads/2024/10/img-20240913-wa0037-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3445\" src=\"/uploads/2024/10/img-20240913-wa0048-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3446\" src=\"/uploads/2024/10/img-20240914-wa0054-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3447\" src=\"/uploads/2024/10/img-20240914-wa0081-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3448\" src=\"/uploads/2024/10/img-20240914-wa0093-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3449\" src=\"/uploads/2024/10/img-20240914-wa0103-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3450\" src=\"/uploads/2024/10/img-20240914-wa0167-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3451\" src=\"/uploads/2024/10/img-20240914-wa0192-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3452\" src=\"/uploads/2024/10/img-20240914-wa0208-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3453\" src=\"/uploads/2024/10/img-20240914-wa0268-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3454\" src=\"/uploads/2024/10/img-20240914-wa0299-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3455\" src=\"/uploads/2024/10/img-20240914-wa0325-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3456\" src=\"/uploads/2024/10/img-20240914-wa0333-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3457\" src=\"/uploads/2024/10/img-20240915-wa0023-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3458\" src=\"/uploads/2024/10/img-20240915-wa0029-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'Perkemahan Penerimaan Tamu Ambalan telah dilaksanakan hari Jum\'at-Sabtu, 13-14 September 2024.ndengan mengusung tema \"Menjadikan Jiwa Kepemimpinan sebagai Karak...', 'publish', 'post', '/uploads/2024/10/img-20241020-wa0006-scaled.webp', 864, 4, '2024-10-20 06:25:41', 'Perkemahan Penerimaan Tamu Ambalan - SMA IT Ishlahul Ummah', 'Perkemahan Penerimaan Tamu Ambalan telah dilaksanakan hari Jum\'at-Sabtu, 13-14 September 2024.ndengan mengusung tema \"Menjadikan Jiwa Kepemimpinan seb...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (280, 'Upacara Peringatan Hari Kemerdekaan RI ke-79', 'upacara-peringatan-hari-kemerdekaan-ri-ke-79', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Upacara Kemerdekaan Republik Indonesia</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dirgahayu Republik Indonesia</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Merdeka berpikir, sebagai pelajar bertanggung jawab terhadap amanah yang diberikan orangtua dengan semangat dalam belajar, mengutamakan adab sebelum ilmu (adab yang baik disertai ilmu yang baik)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">petugas upacara adalah gabungan peserta didik SMA dan SMP. Adapun petugas upacara dari SMA diantaranya :</p><ol><li>M. Abi Khatim Al Habsy Lubis sebagai Pemimpin Upacara (XII Gaza)</li><li>Alief Rasya Arrafi sebagai MC Bahasa Indonesia (XII Gaza)</li><li>Katrinajah Sabilillah sebagai MC Bahasa Inggris (XII Gaza)</li><li>Tsabitah Aulia sebagai MC Bahasa Arab</li><li>M. Naufal Rohmattullah sebagai Ajudan pembina upacara (XII Gaza)</li><li>Toby Aldinata Timothy sebagai pembawa teks pancasila (XII Gaza)</li><li>M. Faiz Arrahman sebagai pembawa teks proklamasi (XI Al Quds)</li><li>Nadia Shakila sebagai pembaca teks UUD 1945 (XII Gaza)</li><li>Arsyil Ammarvallen Shultanik sebagai pembaca Do\'a (X Al Aqsho)</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3387\" src=\"/uploads/2024/09/img-20240817-wa0044-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3388\" src=\"/uploads/2024/09/img-20240817-wa0046-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3389\" src=\"/uploads/2024/09/img-20240817-wa0049-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3390\" src=\"/uploads/2024/09/img-20240817-wa0050-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3391\" src=\"/uploads/2024/09/img-20240817-wa0055-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3392\" src=\"/uploads/2024/09/img-20240817-wa0097-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3393\" src=\"/uploads/2024/09/img-20240817-wa0108-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3394\" src=\"/uploads/2024/09/img-20240817-wa0012-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3395\" src=\"/uploads/2024/09/img-20240817-wa0016-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3396\" src=\"/uploads/2024/09/img-20240817-wa0029-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'Upacara Kemerdekaan Republik IndonesianDirgahayu Republik IndonesianMerdeka berpikir, sebagai pelajar bertanggung jawab terhadap amanah yang diberikan orangtua...', 'publish', 'post', '/uploads/2024/09/website-2024zip-2.webp', 537, 4, '2024-09-12 10:54:23', 'Upacara Peringatan Hari Kemerdekaan RI ke-79 - SMA IT Ishlahul Ummah', 'Upacara Kemerdekaan Republik IndonesianDirgahayu Republik IndonesianMerdeka berpikir, sebagai pelajar bertanggung jawab terhadap amanah yang diberikan...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (281, 'PROYEK SEDEKAH SAMPAH', 'proyek-sedekah-sampah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">#proyek Sedekah Sampah Alhamdulillah dalam rangka memeriahkan HUT RI ke-79, Pemerintah Kota Prabumulih mengadakan Lomba Gerak Jalan, SMAIT Ishlahul Ummah ikut berpartisipasi dengan gerakan aksi Tanggap dengan Lingkungan Prabumulih. Melalui gerakan ini Keluarga SMAIT Ishlahul Ummah Prabumulih berupaya membersihkan jalanan dari sampah plastik maupun kertas.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3378\" src=\"/uploads/2024/09/img-20240814-wa0004-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3379\" src=\"/uploads/2024/09/img-20240814-wa0027-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3381\" src=\"/uploads/2024/09/img-20240814-wa0065-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3382\" src=\"/uploads/2024/09/img-20240814-wa0066-169x300.webp\" alt=\"\" width=\"169\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3384\" src=\"/uploads/2024/09/img-20240814-wa0082-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p>n', '#proyek Sedekah Sampah Alhamdulillah dalam rangka memeriahkan HUT RI ke-79, Pemerintah Kota Prabumulih mengadakan Lomba Gerak Jalan, SMAIT Ishlahul Ummah ikut b...', 'publish', 'post', '/uploads/2024/09/website-2024zip-3.webp', 517, 4, '2024-09-12 10:17:06', 'PROYEK SEDEKAH SAMPAH - SMA IT Ishlahul Ummah', '#proyek Sedekah Sampah Alhamdulillah dalam rangka memeriahkan HUT RI ke-79, Pemerintah Kota Prabumulih mengadakan Lomba Gerak Jalan, SMAIT Ishlahul Um...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (282, 'IU CARE', 'iu-care-2', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Salah satu program unggulan SMAIT Ishlahul Ummah Prabumulih adalah Projek Sosial (IU Care),dan pada kesempatan kali ini dengan Berbagi kebahagiaan bersama anak-anak yatim disekitar lingkungan sekolah. Kegiatan ini tentunya didukung oleh UPZ Ishlahul Ummah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Siswa/i terlibat aktif dalam kegiatan ini mulai dari survey, merancang acara sampai pada hari puncaknya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini bertujuan untuk menumbuhkan kepedulian dan tanggap terhadap permasalahan lingkungan sekitar.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">#generasitanggaptangkastangguh</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3355\" src=\"/uploads/2024/09/img-20240719-wa0061-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3356\" src=\"/uploads/2024/09/img-20240801-wa0025-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3357\" src=\"/uploads/2024/09/img-20240801-wa0026-169x300.webp\" alt=\"\" width=\"169\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3358\" src=\"/uploads/2024/09/img-20240802-wa0005-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3359\" src