  (283, 'Memasak Lauk Khas Sumatera Selatan', 'memasak-lauk-khas-sumatera-selatan', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SEDEKAH JUM\'AT-Memasak Lauk \"Sumsel <em>Pride\"</em><strong> Pindang Ikan</strong></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah Jum\'at, 19 Juli 2024 siswa/i baru SMAIT Ishum didampingi oleh mentor memasak pindang ikan yang kemudian hasil masakannya dibagikan kepada Jemaah Masjid Ananggubir Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Baarakallahufiikum sholih/sholihah, ustad/ustdzah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">#Tanggaptangkastangguh #mendidiksepenuhcinta</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3347\" src=\"/uploads/2024/09/img-20240719-wa0035-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3349\" src=\"/uploads/2024/09/img-20240719-wa0041-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3350\" src=\"/uploads/2024/09/img-20240719-wa0019-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3351\" src=\"/uploads/2024/09/img-20240719-wa0022-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3352\" src=\"/uploads/2024/09/img-20240719-wa0026-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'SEDEKAH JUM\'AT-Memasak Lauk \"Sumsel Pride\" Pindang IkannAlhamdulillah Jum\'at, 19 Juli 2024 siswa/i baru SMAIT Ishum didampingi oleh mentor memasak pindang ikan...', 'publish', 'post', '/uploads/2024/09/website-2024zip-28.webp', 951, 4, '2024-09-12 05:56:23', 'Memasak Lauk Khas Sumatera Selatan - SMA IT Ishlahul Ummah', 'SEDEKAH JUM\'AT-Memasak Lauk \"Sumsel Pride\" Pindang IkannAlhamdulillah Jum\'at, 19 Juli 2024 siswa/i baru SMAIT Ishum didampingi oleh mentor memasak pin...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (284, 'NOBAR FILM KAHF \"Demi Masa\"', 'nobar-film-kahf-demi-masa', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada hari Kamis, 18 Juli 2024 SMAIT Ishlahul Ummah telah menyelenggarakan kegiatan Mabit \"Malam Bina Iman dan Taqwa\". Adapun rangkaian kegiatan pada mabit diantaranya Sholat magrib dan Isya\' berjamaah, dilanjutkan dengan makan malam. Kemudian, kegiatan Nobar (nonton bareng).</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">di Era teknologi yang terus berkembang menjadikan teknologi sebagai sumber untuk belajar melalui program film yang tentunya mendidik. SMAIT Ishlahul Ummah memanfaatkan Film sebagai media pembelajaran. pada kali ini, Film yang diputar adalah film karya KAHF yang berjudul \"Demi Masa\".</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan NOBAR dipandu oleh ustadzah Sesiana Giovani Lestari, S.Pd dan dibersamai juga oleh seluruh guru SMAIT Ishlahul Ummah. Setelah peserta didik menonton film, mereka diajak untuk menghubungkan film yang ditonton dengan kehidupan mereka. pertanyaan pemantik pada film ini adalah tentang <em>Time Management </em>selaras dengan film yang ditonton yakni \"Demi Masa\"</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kemudian peserta didik menyampaikan tanggapan pribadi mereka tentang <em>Time Management.</em></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Setiap orang diberikan jatah waktu yang sama yakni 24 jam oleh Allah swt. Salah satu peserta didik yakni Satria Wibawa menyampaikan hikmah yang didapat dari film Demi Masa.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">\"maka dari film yang berjudul \"Demi Masa\" kita menjadi tahu mana hal yang harus didahulukan, kalau di dalam islam tahu mana yang wajib, sunnah dan haram\" jelasnya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3303\" src=\"/uploads/2024/08/nobar-film-kahfpng-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3302\" src=\"/uploads/2024/08/whatsapp-image-2024-08-04-at-063528-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3300\" src=\"/uploads/2024/08/whatsapp-image-2024-08-04-at-063349-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3301\" src=\"/uploads/2024/08/whatsapp-image-2024-08-04-at-063443-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'Pada hari Kamis, 18 Juli 2024 SMAIT Ishlahul Ummah telah menyelenggarakan kegiatan Mabit \"Malam Bina Iman dan Taqwa\". Adapun rangkaian kegiatan pada mabit diant...', 'publish', 'post', '/uploads/2024/08/website-2024zip-21.webp', 606, 4, '2024-08-04 21:30:22', 'NOBAR FILM KAHF \"Demi Masa\" - SMA IT Ishlahul Ummah', 'Pada hari Kamis, 18 Juli 2024 SMAIT Ishlahul Ummah telah menyelenggarakan kegiatan Mabit \"Malam Bina Iman dan Taqwa\". Adapun rangkaian kegiatan pada m...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (285, 'SMAIT Ishlahul Ummah menyelenggarakan Penandatanganan Deklarasi Anti Kekerasan', 'smait-ishlahul-ummah-menyelenggarakan-penandatanganan-deklarasi-anti-kekerasan', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dalam upaya menciptakan lingkungan belajar yang aman, nyaman dan bebas dari segala bentuk kekerasan, SMAIT Ishlahul Ummah menyelenggarakan penandatanganan Deklarasi Anti Kekerasan. Acara ini berlangsung dengan penuh khidmat pada Senin, 15 Juli 2024.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Deklarasi ini ditandatangani langsung oleh Kepala SMAIT Ishlahul Ummah, Ustzah Anita Carlyna, S.IP, M.Pd dan diikuti oleh seluruh guru, karyawan, serta peserta didik SMAIT Ishlahul Ummah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Penandatanganan ini menjadi bentuk nyata komitmen sekolah dalam melawan segala bentuk perundungan dan kekerasan yang mungkin terjadi di lingkungan sekolah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Para peserta didik baru telah dibekali dengan berbagai materi yang tidak hanya mengarahkan mereka untuk mengenal lingkungan sekolah, tetapi juga menanamkan nilai-nilai moral dan etika, termasuk pentingnya menghormati satu sama lain dan menolak segala bentuk kekerasan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Deklarasi ini juga menegaskan bahwa SMAIT Ishlahul Ummah tidak akan mentolerir segala bentuk perundungan dan kekerasan. Sekolah akan secara tegas menangani setiap kasus yang muncul dengan mengutamakan kepentingan dan kesejahteraan siswa/i.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Hal ini menjadi momen bersejarah bagi SMAIT Ishlahul Ummah yang kini telah menetapkan langkah tegas dalam upaya pencegahan dan penanggulangan perundungan di lingkungan sekolah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3290\" src=\"/uploads/2024/08/deklarasi-anti-kekerasan-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /></p>n', 'Dalam upaya menciptakan lingkungan belajar yang aman, nyaman dan bebas dari segala bentuk kekerasan, SMAIT Ishlahul Ummah menyelenggarakan penandatanganan Dekla...', 'publish', 'post', '/uploads/2024/08/website-2024zip-20.webp', 1465, 4, '2024-08-04 20:16:55', 'SMAIT Ishlahul Ummah menyelenggarakan Penandatanganan Deklarasi Anti Kekerasan - SMA IT Ishlahul Ummah', 'Dalam upaya menciptakan lingkungan belajar yang aman, nyaman dan bebas dari segala bentuk kekerasan, SMAIT Ishlahul Ummah menyelenggarakan penandatang...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (286, 'MPLS 2024 SMAIT Ishlahul Ummah Prabumulih', 'pelajar-pancasila-yang-tanggap-tangkas-dan-tangguh-untuk-perbaikan-umat-masa-kini-dan-nanti-smait-ishlahul-ummah-mengadakan-mpls-ke-6-nya-di-tahun-pelajaran-2024-2025', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">MPLS merupakan kegiatan orientasi di sekolah yang bertujuan untuk mengenalkan program pendidikan, fasilitas sekolah, metode belajar, memperkenalkan konsep pengenalan diri, serta membangun dan membiasakan karakter budaya sekolah yang positif. MPLS diadakan selama satu pekan pada tahun pelajaran baru, di hari sekolah dan jam pelajaran yang telah ditentukan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada tanggal 15 Juli 2024, sebanyak 12 siswa dinyatakan diterima di SMAIT Ishlahul Ummah. Setelah dinyatakan diterima, mereka mengikuti kegiatan MPLS (Masa Pengenalan Lingkungan Sekolah). Kegiatan ini diawali dengan Apel Pagi Pembukaan MPLS di SMAIT Ishlahul Ummah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dengan mengusung tema MPLS yakni \"Pelajar Pancasila yang Tanggap, Tangkas dan Tangguh untuk Perbaikan Umat Masa Kini dan Nanti\", SMAIT Ishlahul Ummah berupaya membentuk peserta didik berjiwa pemimpin yang tanggap, tangkas dan tangguh di lingkungan manapun mereka berada.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">MPLS telah diadakan selama satu pekan dari tanggal 15 - 19 Juli 2024 diikuti oleh 12 siswa/siswi SMAIT Ishlahul Ummah meliputi siswa/i kelas X, XI dan XII. Materi MPLS SMAIT Ishlahul Ummah hari pertama mencakup:</p><ul><li>Pembekalan Materi Struktur Organisasi Sekolah</li><li>Penjelasan Fiqih Thoharoh</li><li>Penjelasan Adab dalam menuntut Ilmu</li><li>Penjelasan Materi Anti Kekerasan</li><li>Pengenalan Organisasi</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kemudian, Materi MPLS SMAIT Ishlahul Ummah hari kedua meliputi:</p><ul><li>Pembekalan Materi Fiqih Sholat</li><li>Penjelasan Adab Berbicara</li><li>Diskusi bersama Mentor</li><li>Melakukan Survei Masjid radius 1 km di sekitar sekolah sebagai bahan untuk program Sedekah Jum\'at (jum\'at berkah)</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan MPLS SMAIT Ishlahul Ummah hari ketiga diantaranya:</p><ul><li>Merancang Konsep Jum\'at Berkah (sedekah jum\'at)</li><li>Melakukan Budgeting sampai mengkonsep proses pembuatan masakan jum\'at berkah</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan MPLS SMAIT Ishlahul Ummah hari keempat diantaranya:</p><ul><li>Siswa/i baru didampingi mentor berbelanja ke pasar untuk membeli bahan masakan untuk jum\'at berkah</li><li>Latihan Baris Berbaris (Pramuka)</li><li>Nonton Bareng film Kahf-Demi Masa</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan MPLS SMAIT Ishlahul Ummah pada hari terakhir mencakup:</p><ul><li>Olahraga Pagi</li><li>Memasak lauk khas Sumatera Selatan untuk Jum\'at Berkah</li><li>Pembagian Jum\'at berkah sebanyak 47 pack Nasi + Pindang Ikan/pepes ikan patin kepada jamaah sholat jum\'at di Masjid Ananggubir</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Terima kasih dan selamat atas keberhasilan putra-putri Ayah/Bunda menjadi bagian dari keluarga besar SMAIT Islahul Ummah Prabumulih. Kami juga mengucapkan terima kasih banyak karena Ayah/Bunda telah memberikan kepercayaan kepada SMAIT Ishlahul Ummah untuk mendidik Putra-putri Ayah/Bunda.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kami berkomitmen untuk memberikan pendidikan yang terbaik dan mendukung perkembangan mereka dengan baik di lingkungan sekolah kami. Semoga Putra-putri kita dapat meraih kesuksesan dan prestasi yang gemilang di masa depan dan tentunya bermanfaat bagi lingkungan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Terima kasih sekali lagi atas kepercayaan yang diberikan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Generasi Tanggap Tangkas dan Tangguh</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Menuju Indonesia EMAS</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">#mendidiksepenuhcinta</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3281\" src=\"/uploads/2024/08/img-20240804-wa0022-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3283\" src=\"/uploads/2024/08/img-20240804-wa0024-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3280\" src=\"/uploads/2024/08/img-20240804-wa0021-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3279\" src=\"/uploads/2024/08/img-20240804-wa0020-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3282\" src=\"/uploads/2024/08/img-20240804-wa0023-287x300.webp\" alt=\"\" width=\"287\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3268\" src=\"/uploads/2024/08/img-20240804-wa0009-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3269\" src=\"/uploads/2024/08/img-20240804-wa0010-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3270\" src=\"/uploads/2024/08/img-20240804-wa0011-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3271\" src=\"/uploads/2024/08/img-20240804-wa0012-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3272\" src=\"/uploads/2024/08/img-20240804-wa0013-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3274\" src=\"/uploads/2024/08/img-20240804-wa0015-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3275\" src=\"/uploads/2024/08/img-20240804-wa0016-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3277\" src=\"/uploads/2024/08/img-20240804-wa0018-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /><img class=\"alignnone size-medium wp-image-3276\" src=\"/uploads/2024/08/img-20240804-wa0017-288x300.webp\" alt=\"\" width=\"288\" height=\"300\" /></p>n', 'MPLS merupakan kegiatan orientasi di sekolah yang bertujuan untuk mengenalkan program pendidikan, fasilitas sekolah, metode belajar, memperkenalkan konsep penge...', 'publish', 'post', '/uploads/2024/08/website-2024zip-19.webp', 582, 4, '2024-08-04 17:37:10', 'MPLS 2024 SMAIT Ishlahul Ummah Prabumulih - SMA IT Ishlahul Ummah', 'MPLS merupakan kegiatan orientasi di sekolah yang bertujuan untuk mengenalkan program pendidikan, fasilitas sekolah, metode belajar, memperkenalkan ko...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (287, 'Sehat itu Mahal, Tidak Merokok itu Keren', 'sehat-itu-mahal-tidak-merokok-itu-keren', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Anak muda zaman sekarang, mulai menormalisasikan merokok sebagai kebiasaan dan merokok merupakan suatu hal yang keren. Padahal rokok itu berbahaya loh! Mengapa rokok itu berbahaya? Dilansir dari P2PTM Kemenkes RI, rokok berisi lebih dari 4.000 senyawa kimia, 400 zat berbahaya, dan 43 zat karsinogenik meliputi, karbon monoksida (CO), tar, nikotin, hidrogen sianida dan bahan lainnya yang sangat berbahaya bagi tubuh manusia dan dapat menyebabkan kematian. Tanpa disadari ternyata banyak sekali dampak yang ditimbulkan oleh merokok, diantaranya adalah kanker paru-paru, impotensi, stroke dan jantung. Selain bagi perokok aktif, dampak dari rokok dapat juga dirasakan oleh orang yang menghirup asap rokok tersebut, atau biasa disebut sebagai perokok pasif. Dampak yang dirasakan oleh perokok pasif 30% lebih parah jika dibandingkan dengan perokok aktif (Sodik, M.A, M. Ali., 2018).</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sudah banyak anak remaja yang mengetahui bahwa rokok itu berbahaya. Namun, mereka menganggap dampak merokok ini sepele, dikarenakan dampaknya tidak langsung dirasakan pada saat mereka merokok namun, dampaknya baru dapat dirasakan di masa tua. Berdasarkan data Badan Pusat Statistik, persentase merokok tertinggi pada penduduk umur lebih dari 15 tahun menurut provinsi pada tahun 2023 adalah pada posisi pertama ada provinsi Lampung dengan jumlah perokok 34,08%, pada posisi kedua ada provinsi Nusa Tenggara Barat (NTB) dengan jumlah perokok 32,79%, posisi ketiga ada provinsi  Bengkulu dengan jumlah perokok 31,86%, dan sedangkan Sumatera Selatan berada di posisi keempat dengan jumlah perokok 30,91%. Dari data yang tersedia dapat disimpulkan bahwa tingkat perokok pada usia remaja di Indonesia terbilang cukup tinggi.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Jumlah perokok usia remaja di Indonesia paling tinggi pada rentang usia 15 tahun ke atas. Hal ini dapat terjadi karena para remaja menganggap bahwa merokok merupakan aktivitas santai yang dapat dilakukan untuk menghilangkan stress dan menjadi salah satu cara untuk menenangkan pikiran. dr. Mudjiran, seorang konselor dan dosen psikologi UNP mengemukakan bahwa merokok tidak ada kaitannya sama sekali dengan stress, depresi, ataupun masalah psikologis lainnya. Jika ada anak muda yang merokok untuk mengatasi stress, maka perilaku merokok itu hanya sebuah pelarian (Sodik, M.A, M. Ali., 2018). Faktor lainnya adalah pengaruh dari lingkungan dan rasa ingin tahu yang tinggi pada usia remaja sehingga banyak remaja yang awalnya hanya mencoba rokok dan berakhir kecanduan dengan rokok tersebut.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dilansir dari Pustaka Unand menurut pandangan agama Islam, merokok dapat menjerumuskan dalam kebinasaan, yaitu merusak seluruh sistem tubuh (menimbulkan penyakit kanker, penyakit pernafasan, jantung, pencernaan, berefek buruk bagi janin, dan merusak sistem reproduksi), dari alasan ini sangat jelas rokok terlarang atau haram.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ada beberapa cara agar terhindar dari rokok, diantaranya; menjauhi lingkungan orang-orang yang merokok, mencari tahu lebih lanjut tentang bahaya dari merokok, dan melakukan hal-hal positif seperti, berolahraga atau melakukan hobi kalian. Dikutip dari Kemenkes RI, jika sudah terlanjur merokok maka lakukan langkah-langkah berikut untuk berhenti dari merokok, kelola stress kalian dengan baik, hindari pemicu kebiasaan merokok, mengonsumsi makanan yang sehat, mengurangi frekuensi merokok dan jumlah rokok secara bertahap, kemudian minta bantuan dokter dan yang paling penting adalah bulatkan tekad dan tujuan kalian untuk berhenti merokok.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pesan penulis untuk seluruh anak remaja diluar sana, sayangi tubuh kalian, keluarga kalian dan lingkungan sekitar kalian dengan tidak merokok. Yakinkan diri kalian bahwa merokok bukanlah satu-satunya sarana untuk mendapatkan teman, masih banyak sarana lain untuk mendapatkan teman. Oleh karena itu, dengan tidak merokok kita sudah menjaga kesehatan paru-paru kita sebagai investasi di masa tua nantinya. Stop merokok! Karena sehat itu mahal, tidak merokok itu keren.</p>n', 'Anak muda zaman sekarang, mulai menormalisasikan merokok sebagai kebiasaan dan merokok merupakan suatu hal yang keren. Padahal rokok itu berbahaya loh! Mengapa...', 'publish', 'post', '/uploads/2024/07/img-20240703-wa0057.webp', 593, 4, '2024-07-04 08:27:45', 'Sehat itu Mahal, Tidak Merokok itu Keren - SMA IT Ishlahul Ummah', 'Anak muda zaman sekarang, mulai menormalisasikan merokok sebagai kebiasaan dan merokok merupakan suatu hal yang keren. Padahal rokok itu berbahaya loh...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (288, 'Arabic Class for Teacher Lv. 1', 'arabic-class-for-teacher', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMAIT ISHUM NEWS~~ ARABIC CLASS FOR TEACHER LV. 1</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Program ini diperuntukan bagi seluruh guru SMAIT bersifat wajib, dan alhamdulillah diikuti juga oleh dua orang guru lainnya dari unit TK. Program ini berjalan satu minggu sekali di setiap hari jum\'at siang dengan tujuan menggali skill bahasa asing demi menunjang program arabic day bersama siswa-siswi.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Program ini dipimpin langsung oleh Kepala Sekolah dan dibimbing langsung oleh Mentor di bidangnya yaitu Ustadz Agi Gustiawan, S.Pd.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, para guru bisa mengikuti dengan baik bahkan semuanya tuntas pada ujian level 1 yang diujikan kemarin 20 Juni 2024.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga program ini membawa perubahan terutama di bidang bahasa arab, agar siswa-siswi terbiasa mendengar dan berkomunikasi dengan bahasa yang dianjurkan Rasulullah SAW yaitu bahasa arab.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3206\" src=\"/uploads/2024/06/img-20240621-wa0004-300x226.webp\" alt=\"\" width=\"300\" height=\"226\" /></p>n', 'SMAIT ISHUM NEWS~~ ARABIC CLASS FOR TEACHER LV. 1nProgram ini diperuntukan bagi seluruh guru SMAIT bersifat wajib, dan alhamdulillah diikuti juga oleh dua orang...', 'publish', 'post', '/uploads/2024/06/website-2024-20240621-203545-0000.webp', 876, 4, '2024-06-21 21:09:28', 'Arabic Class for Teacher Lv. 1 - SMA IT Ishlahul Ummah', 'SMAIT ISHUM NEWS~~ ARABIC CLASS FOR TEACHER LV. 1nProgram ini diperuntukan bagi seluruh guru SMAIT bersifat wajib, dan alhamdulillah diikuti juga oleh...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (289, 'Rapat Komite & Pembagian Rapor X & XI', 'rapat-komite-pembagian-rapor-x-xi', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMAIT ISHUM NEWS~~ RAPAT KOMITE, PEMBAGIAN RAPOR X, XI</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Telah usai pelaporan perkembangan sekolah dan siswa kepada komite sekolah. Kemudian dilanjutkan dengan pergantian pengurus komite, adapun Ketua Komite Terpilih untuk TP. 2024/2025 yaitu Bapak Rusdi Efendi. Adapun dalam sambutan kepala sekolah Ustadzah Anita dalam kesempatan ini beliau menyampaikan kabar gembira, bahwa SMA IT Ishlahul Ummah Prabumulih tahun ini berhasil mempertahankan predikat sekolah berkemajuan terbaik dari kemendikbudristek dari tahun 2023 hingga tahun ini dengan dua tahun berturut-turut.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Setelah rapat komite berjalan lancar, kegiatan selanjutnya dilanjutkan dengan pembagian hasil belajar selama semester genap untuk kelas X dan XI bersama wali kelas masing-masing.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3199\" src=\"/uploads/2024/06/img-20240621-wa0002-300x153.webp\" alt=\"\" width=\"300\" height=\"153\" /></p>n', 'SMAIT ISHUM NEWS~~ RAPAT KOMITE, PEMBAGIAN RAPOR X, XInTelah usai pelaporan perkembangan sekolah dan siswa kepada komite sekolah. Kemudian dilanjutkan dengan pe...', 'publish', 'post', '/uploads/2024/06/website-2024-20240621-202040-0000.webp', 563, 4, '2024-06-21 20:54:14', 'Rapat Komite & Pembagian Rapor X & XI - SMA IT Ishlahul Ummah', 'SMAIT ISHUM NEWS~~ RAPAT KOMITE, PEMBAGIAN RAPOR X, XInTelah usai pelaporan perkembangan sekolah dan siswa kepada komite sekolah. Kemudian dilanjutkan...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (290, 'WISUDA AKBAR', 'wisuda-akbar', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMAIT ISHUM NEWS~~WISUDA AKBAR TAHFIDZ QUR\'AN</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan wisuda akbar diperuntukan bagi siswa non kelas akhir dari tingkat SD sampai SMA yang sudah menuntaskan hafalan ziyadahnya minimal 1 juz. Adapun jumlah peserta kurang lebih 170an siswa siswi dengan berbagai predikat hafalan. Jumlah hafalan paling banyak diraih oleh dua siswa SMAIT yaitu Abi dan Alief dengan hafalan 5 Juz.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Barakallah, semoga ananda istiqomah dalam menghafal dan memurojaahnya serta mampu mengaplikasikan kandungan Al Qur\'an dalam adab dan akhlak di kehidupan sehari-hari.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3185\" src=\"/uploads/2024/06/whatsapp-image-2024-06-19-at-122103-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'SMAIT ISHUM NEWS~~WISUDA AKBAR TAHFIDZ QUR\'ANnKegiatan wisuda akbar diperuntukan bagi siswa non kelas akhir dari tingkat SD sampai SMA yang sudah menuntaskan ha...', 'publish', 'post', '/uploads/2024/06/siswa-berprestasi-2024-1280-x-720-piksel6.webp', 332, 4, '2024-06-19 08:31:29', 'WISUDA AKBAR - SMA IT Ishlahul Ummah', 'SMAIT ISHUM NEWS~~WISUDA AKBAR TAHFIDZ QUR\'ANnKegiatan wisuda akbar diperuntukan bagi siswa non kelas akhir dari tingkat SD sampai SMA yang sudah menu...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (291, 'FAMILY GATHERING ANGKATAN III 2024', 'family-gathering-angkatan-iii-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMAIT ISHUM NEWS ~~Senin, 06 Mei 2024 Hall Ishlahul Ummah telah berlangsung Family Gathering angkatan ke III yang dihadiri oleh seluruh wali murid kelas XII dalam rangka meningkatkan ukhuwah sekaligus kegiatan terakhir khusus ananda kelas XII beserta ayah dan bundanya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dalam kesempatan ini, turut juga Abang Muaz selaku Manager Hall Ishum sekaligus mewakili Pembina Yayasan Ishlahul Ummah yang berhalangan hadir yaitu Ust. H. Mat Amin, S.Ag. Beliau berpesan kepada anak didik kelas XII untuk terus melanjutkan pendidikan yang lebih tinggi, menggapai asa dan jangan mudah menyerah. Dan tidak lupa mengingatkan untuk menjaga sholat sebagai tiang agama dan memurojaah hafalan qur\'an dan hadits yang sudah diperoleh selama bersekolah di SMA IT Ishlahul Ummah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dalam rangkaian kegiatan ini terdapat pemberian reward prestasi kepada Ananda Zen selaku siswa berprestasi dengan hafalan Qur\'an 4 Juz dan 42 Hadits Arbain, serta ananda Yunita sebagai pemenang OSN-K Juara III bidang Kimia tingkat Kota Tahun 2023.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini berlangsung hikmat dan penuh haru, orang tua bangga dengan segala pencapaian ananda, dan para ustadz ustadzah bahagia melepas ananda untuk melangkah ke jenjang yang lebih tinggi.(08/05/2024)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3096\" src=\"/uploads/2024/05/whatsapp-image-2024-05-06-at-114329-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3097\" src=\"/uploads/2024/05/whatsapp-image-2024-05-06-at-095859-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3098\" src=\"/uploads/2024/05/whatsapp-image-2024-05-06-at-095505-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'SMAIT ISHUM NEWS ~~Senin, 06 Mei 2024 Hall Ishlahul Ummah telah berlangsung Family Gathering angkatan ke III yang dihadiri oleh seluruh wali murid kelas XII dal...', 'publish', 'post', '/uploads/2024/05/siswa-berprestasi-2024-1280-x-720-piksel2.webp', 884, 4, '2024-05-08 09:30:16', 'FAMILY GATHERING ANGKATAN III 2024 - SMA IT Ishlahul Ummah', 'SMAIT ISHUM NEWS ~~Senin, 06 Mei 2024 Hall Ishlahul Ummah telah berlangsung Family Gathering angkatan ke III yang dihadiri oleh seluruh wali murid kel...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (292, 'STUDI TIRU 2024', 'studi-tiru-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMAIT ISHUM NEWS~Kamis, 02 Mei 2024 lalu bertepatan dengan HARDIKNAS, SMA IT Ishum melakukan perjalanan ke Bengkulu dalam rangka kegiatan STUDI TIRU ke SMA IT Iqro\' Bengkulu. Dalam rombongan ini ikut serta juga Ummi Fasma selaku Ketua Yayasan Ishum serta Ustadzah Yani selaku Manajer Operasional Ishum dan beberapa guru serta siswa pilihan turut ikut dalam kegiatan ini.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Tiba di lokasi, kami disambut meriah oleh siswa-siswi SMA IT Iqro\' dan juga turun langsung Ketua Yayasan Alfida yang menaungi SMA IT Iqro\'. Adapun acara pembukaan dibuka langsung oleh Ustad. Dr. Dani Hamdani selaku Ketua Yayasan Alfida. Dalam sambutannya kami semua mendapatkan banyak inspirasi salah satunya adalah kunci kesuksesan dalam pendidikan yang mereka lakoni yaitu Tarbiyah (pendidikan) guru atau pembinaan guru.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga ikatan silahturahmi terjalin erat dan berkesinambungan. Serta mampu bersinergi untuk mencerdaskan generasi bangsa dalam naungan JSIT.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3087\" src=\"/uploads/2024/05/img-8721-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" /> <img class=\"alignnone size-medium wp-image-3088\" src=\"/uploads/2024/05/img-8665-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'SMAIT ISHUM NEWS~Kamis, 02 Mei 2024 lalu bertepatan dengan HARDIKNAS, SMA IT Ishum melakukan perjalanan ke Bengkulu dalam rangka kegiatan STUDI TIRU ke SMA IT I...', 'publish', 'post', '/uploads/2024/05/siswa-berprestasi-2024-1280-x-720-piksel1.webp', 1718, 4, '2024-05-05 16:23:03', 'STUDI TIRU 2024 - SMA IT Ishlahul Ummah', 'SMAIT ISHUM NEWS~Kamis, 02 Mei 2024 lalu bertepatan dengan HARDIKNAS, SMA IT Ishum melakukan perjalanan ke Bengkulu dalam rangka kegiatan STUDI TIRU k...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (293, 'Gen Z, Lemah MENTAL?', 'gen-z-lemah-mental', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT ISHUM News -- Gen Z benarkah generasi yang mudah putus asa? insecure? mudah tersentuh? atau lemah mental? Kita tahu bahwa Gen Z adalah generasi yang lahir dari tahun 1997 s.d 2012 yang mana menjadi gen dominan yang memenuhi masyarakat Indonesia pada masa emas tahun 2045 nanti.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Namun, yang harus kita sadari Gen Z lahir pada masa internet sudah berjaya sampai ke pelosok dunia. Modernisasi baik dari segi fasilitas, pendidikan, ekonomi dll adalah hal yang cukup besar mempengaruhi tingkat karakter masyarakat. Sehingga semua akses dan kemudahan yang didapat membuat Gen Z bermalas-malasan dan kurang effort untuk mendapatkan sesuatu karena begitu mudahnya menjalani hidup saat ini mulai dari transanksi online, belanja online, bahkan semua jenis apk games online dan chatting online tersedia dalam satu jenis perangkat yaitu handphone.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Anehnya dengan semua bentuk kemudahan itu, Gen Z menjadi generasi yang mudah putus asa, mudah emosional dan tidak respect terhadap suatu pencapaian diakibatkan oleh budaya konsumtif yang mereka terima dari sejak mereka dalam buaian. Untuk itu, sebagai orang yang bergerak dalam dunia pendidikan perlu kurikulum yang sesuai dengan kondisi anak saat ini. Sehingga tidak bisa lagi digunakan sistem pendidikan terdahulu walaupun yang kita tahu Generasi lampau jauh lebih bagus dari segi mental.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">\"Dan janganlah berputus asa atas rahmat Allah. Sungguh, tiada orang yang berputus asa atas rahmat Allah kecuali orang yang tiada beriman.\" (QS. Yusuf:87)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, SMA IT Ishlahul Ummah menyediakan kurikulum yang berbasis meningkatkan keimanan generasi Z seperti pembiasaan pagi mulai dari dzikir, dhuha dan Tahsin tahfidz qur\'an setiap hari. Sholat dzuhur dan ashar berjamaah. Kajian tematik di setiap jumat, dan juga pembiasaan adab akhlak. Tentu dari semua kurikulum berbasis keimanan ini diimbangi akademik, pergaulan serta nalar pikir yang baik. Untuk mengasah itu mulai tahun ini SMA IT Ishum memberlakukan belajar berbasis project dimana anak akan terjun langsung belajar pada alam dan masyarakat. (Prabumulih, 25 April 2024)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Penulis: AC</p>n', 'SMA IT ISHUM News -- Gen Z benarkah generasi yang mudah putus asa? insecure? mudah tersentuh? atau lemah mental? Kita tahu bahwa Gen Z adalah generasi yang lahi...', 'publish', 'post', '/uploads/2024/04/siswa-berprestasi-20242.webp', 760, 4, '2024-04-25 10:21:30', 'Gen Z, Lemah MENTAL? - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News -- Gen Z benarkah generasi yang mudah putus asa? insecure? mudah tersentuh? atau lemah mental? Kita tahu bahwa Gen Z adalah generasi...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (294, 'Pengumuman Hasil OSN-K Tingkat Kabuten/Kota', 'pengumuman-hasil-osn-k-tingkat-kabuten-kota', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT ISHUM News--Pada Rabu, 17 April 2024, telah diumumkan hasil seleksi Olimpiade Sains Nasional tingkat Kabupaten (OSN-K) tahun 2024. Pada tahun ini, sebanyak 3 orang siswa-siswi SMA IT Ishlahul Ummah Prabumulih berhasil lolos ke tingkat Provinsi dalam Olimpiade Sains Nasional. Adapun siswa-siswi yang telah lolos, diantaranya:</p><ol><li>Muhammad Abi Khatim Alhabsy Lubis (XI. Al-Quds) JUARA I Kimia.</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3065\" src=\"/uploads/2024/04/snapinstaapp-437684195-18056680465566334-680969753239597528-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><ol><li>Katrinajah Sabilillah (XI. Al-Quds) JUARA III Biologi.</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3067\" src=\"/uploads/2024/04/snapinstaapp-437947509-18056680477566334-8043093377291905900-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><ol><li>Toby Aldinata Timothy (XI. Al-Quds) JUARA VIII Informatika.</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3066\" src=\"/uploads/2024/04/snapinstaapp-437724925-18056680468566334-3737021705290206288-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun kepala SMA IT ISHUM, Anita Carlyna, S.IP., M.Pd sangat mengapresiasi keberhasilan ananda, yang mana beliau insya Allah sudah menyiapkan berupa reward uang pembinaan bagi yang lolos dengan kategori juara 1 s.d 3. Sesuai dengan pedoman tatib siswa bagi yang berprestasi baik dari segi akademik maupun non-akademik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Lanjutnya beliau juga mengucapkan Selamat kepada siswa-siswi yang telah lolos, untuk terus semangat dalam melanjutkan perjuangan ditingkat Provinsi dan mengharumkan nama baik SMA IT Ishlahul Ummah Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3069\" src=\"/uploads/2024/04/whatsapp-image-2024-04-22-at-091951-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /></p>n', 'SMA IT ISHUM News--Pada Rabu, 17 April 2024, telah diumumkan hasil seleksi Olimpiade Sains Nasional tingkat Kabupaten (OSN-K) tahun 2024. Pada tahun ini, sebany...', 'publish', 'post', '/uploads/2024/04/whatsapp-image-2024-04-22-at-091951-scaled.webp', 915, 4, '2024-04-18 09:32:31', 'Pengumuman Hasil OSN-K Tingkat Kabuten/Kota - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News--Pada Rabu, 17 April 2024, telah diumumkan hasil seleksi Olimpiade Sains Nasional tingkat Kabupaten (OSN-K) tahun 2024. Pada tahun i...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (295, 'IU CARE', 'iu-care', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT ISHUM News-- IU Care adalah program yang bertujuan untuk menanamkan rasa kepedulian sesama saudara Muslim yang membutuhkan terutama pada bulan Ramadhan begitu besar ganjaran pahala bagi mereka yang memudahkan urusan orang yang kesulitan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">IU Care dilaksanakan pada hari Kamis, 04 April 2024 di daerah kelurahan Karang Raja, Prabumulih Timur.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini bekerja sama dengan Unit Pengumpul Zakat Ishlahul Ummah Prabumulih sekaligus pembagian zakat fitrah. Adapun perolehan dana juga berasal dari wali murid dari TK s.d SMA berupa infaq dan shodaqoh.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Al-hamdulillah kegiatan ini diikuti sebagian peserta didik dan didamping oleh ust/ustzh ketika proses pendistribusiannya. Saat ini tercatat kurang lebih 180 paket sembako dan takjil yang sudah tersebar di sekitar lingkungan sekolah kampus karang raja.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga melalui kegiatan ini ukhuwah antara umat muslim semkin terjaga dan mendapatkan pahala disisi Allah SWT.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3053\" src=\"/uploads/2024/04/img-20240404-wa0005-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3054\" src=\"/uploads/2024/04/img-20240404-wa0004-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3055\" src=\"/uploads/2024/04/img-20240406-wa0004-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" /> <img class=\"alignnone size-medium wp-image-3056\" src=\"/uploads/2024/04/img-20240406-wa0003-225x300.webp\" alt=\"\" width=\"225\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3057\" src=\"/uploads/2024/04/img-20240406-wa0005-186x300.webp\" alt=\"\" width=\"186\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3058\" src=\"/uploads/2024/04/img-20240406-wa0009-300x226.webp\" alt=\"\" width=\"300\" height=\"226\" /> <img class=\"alignnone size-medium wp-image-3059\" src=\"/uploads/2024/04/img-20240406-wa0007-300x166.webp\" alt=\"\" width=\"300\" height=\"166\" /></p>n', 'SMA IT ISHUM News-- IU Care adalah program yang bertujuan untuk menanamkan rasa kepedulian sesama saudara Muslim yang membutuhkan terutama pada bulan Ramadhan b...', 'publish', 'post', '/uploads/2024/04/img-20240406-wa0007.webp', 1210, 4, '2024-04-04 16:30:21', 'IU CARE - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News-- IU Care adalah program yang bertujuan untuk menanamkan rasa kepedulian sesama saudara Muslim yang membutuhkan terutama pada bulan...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (296, 'PENGUMUMAN HASIL SNBP 2024', 'pengumuman-hasil-smbp-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>SMA IT ISHUM News--</strong> Baarakallah kepada Ananda Nisaa Trie Antika yang telah diterima di PTN melalui Seleksi Nasional Berdasarkan Prestasi (SNBP 2024)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga Allah mudahkan jalan menuju kesuksesan, Istiqomah dalam kebaikan. Selamat berkarya dan berjuang di Kampus ya ananda ✊ selamat bertumbuh 🌱</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3049\" src=\"/uploads/2024/04/snapinstaapp-434220171-18054550498566334-4372152882803157098-n-1080-1-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'SMA IT ISHUM News-- Baarakallah kepada Ananda Nisaa Trie Antika yang telah diterima di PTN melalui Seleksi Nasional Berdasarkan Prestasi (SNBP 2024)nSemoga Alla...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-434220171-18054550498566334-4372152882803157098-n-1080-1.webp', 1352, 4, '2024-03-26 13:55:43', 'PENGUMUMAN HASIL SNBP 2024 - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News-- Baarakallah kepada Ananda Nisaa Trie Antika yang telah diterima di PTN melalui Seleksi Nasional Berdasarkan Prestasi (SNBP 2024)nS...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (297, 'IU Nyantri', 'iu-nyantri', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>SMA IT ISHUM News--</strong> IU Nyantri adalah program yang bertujuan untuk mengenalkan pola interaksi dan pembelajaran di pondok pesantren.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">IU Nyantri dilaksanakan pada hari Jum’at-Ahad, 22-24 Maret 2024 di pondok pesantren Ibadurrahman Muara Enim.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini diawali pemberangkatan di hari jum’at dan dilepas langsung oleh Manger SIT Ishlahul Ummah Prabumulih Ustazah Mulyani Rahayu, ST., M. Pd didampingi Kabag SDM Ustzh Wita Anjasmara, S.Pd.,AUD</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun beliau berpesan “Semoga melalui kegiatan IU Nyantri ini anak-anak SMA IT ISHUM mampu menyerap ilmu sebanyak-banyaknya.”</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Al-Hamdulillah banyak ilmu dan pengalaman baru yang didapatkan peserta didik melalui kegiatan ini. Salah satunya sebagai berikut :</p><ol><li>Pola interaksi santri</li><li>Budaya pesantren</li><li>Metode menghafal qur’an muttqin</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga melalui kegiatan ini SMA IT ISHUM mampu mencetak generasi qur’ani yang berakhlak mulia.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3045\" src=\"/uploads/2024/04/snapinstaapp-434305767-18054441139566334-6491404645166291112-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3042\" src=\"/uploads/2024/04/snapinstaapp-432772627-18054441121566334-8224592961074154234-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3043\" src=\"/uploads/2024/04/snapinstaapp-434183242-18054441103566334-4657882383159853793-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3044\" src=\"/uploads/2024/04/snapinstaapp-434208176-18054441094566334-1477257153867739978-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" />  <img class=\"alignnone size-medium wp-image-3046\" src=\"/uploads/2024/04/snapinstaapp-434345960-18054441112566334-1650837263796472324-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'SMA IT ISHUM News-- IU Nyantri adalah program yang bertujuan untuk mengenalkan pola interaksi dan pembelajaran di pondok pesantren.nIU Nyantri dilaksanakan pada...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-434208176-18054441094566334-1477257153867739978-n-1080.webp', 1069, 4, '2024-03-25 13:50:49', 'IU Nyantri - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News-- IU Nyantri adalah program yang bertujuan untuk mengenalkan pola interaksi dan pembelajaran di pondok pesantren.nIU Nyantri dilaksa...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (298, 'SUMATIF AKHIR SEMESTER (SAS) GENAP TP.2023-2024', 'sumatif-akhir-semester-sas-genap-tp-2023-2024', '<p style=\"margin-top: 0cm;background: white; text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>SMA IT ISHUM News--</strong> Sumatif Akhir Semester Genap kelas XII tahun pelajaran 2023-2024. Kegiatan ini dilakukan selama enam hari mulai dari tanggal 1-8 Maret 2024 di Gedung sekolah SMA IT Ishlahul Ummah (SMA IT ISHUM) Prabumulih.</p>n<p style=\"margin-top: 0cm;background: white;margin-bottom: 1rem;text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sumatif akhir semester merupakan kegiatan rutin yang dilakukan pada tiap semester. Sumatif ini biasanya digunakan oleh guru sebagai dasar untuk mengukur kemampuan kognitif mata pelajaran yang akan dibagikan hasilnya saat pembagian raport. </p>n<p style=\"margin-top: 0cm;background: white; text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun kepala SMA IT ISHUM, Anita Carlyna, S.IP., M.Pd menjelaskan bahwa \"SAS Kelas Akhir tahun ini sedikit berbeda. Karena sebagai salah satu komponen nilai Ijazah dengan mengambil rata-rata rapor dari semester 1 s.d 6. Sehingga tahun ini kami tidak melakukan USP. Sukses selalu untuk ananda.\"</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2992\" src=\"/uploads/2024/04/snapinstaapp-431410700-18052911634566334-706236191106640125-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2993\" src=\"/uploads/2024/04/snapinstaapp-431642011-18052911625566334-2642295497984198520-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'SMA IT ISHUM News-- Sumatif Akhir Semester Genap kelas XII tahun pelajaran 2023-2024. Kegiatan ini dilakukan selama enam hari mulai dari tanggal 1-8 Maret 2024...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-431374655-18052911643566334-3306612257766624171-n-1080.webp', 470, 4, '2024-03-08 11:54:47', 'SUMATIF AKHIR SEMESTER (SAS) GENAP TP.2023-2024 - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News-- Sumatif Akhir Semester Genap kelas XII tahun pelajaran 2023-2024. Kegiatan ini dilakukan selama enam hari mulai dari tanggal 1-8 M...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (299, 'TARHIB DAN PAWAI RAMADHAN 2024', 'tarhib-dan-pawai-ramadhan-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Marhaban Ya Ramdhan…</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Menyambut bulan suci Ramadhan SMA IT Ishlahul Ummah prabumulih melakukan kegiatan Tarhib dan Pawai Ramadhan di lingkungan sekolah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini diikuti oleh seluruh peserta didik dari SD, SMP dan SMA IT Ishlahul Ummah Prabumulih dan dilaksanakan pada hari Kamis, 7 Maret 2024.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini diawali pawai Ramadhan mengelilingi kelurahan Karang Raja dengan mensyiarkan sholawat, orasi Ramadhan, karoke Islami dan quotes Islami seputar Ramadhan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kemudian setelah kegiatan pawai dilanjutkan materi tarhib Ramadhan yang di sampaikan oleh guru di aula SD &amp; SMP IT ISHUM.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah kegiatan ini sudah dilaksanakan berjalan lancar dan baik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga melalui kegiatan ini menjadikan peserta didik dan masyarakat hamba yang selalu meningkatkan ketaqwaan kepada Allah SWT.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2979\" src=\"/uploads/2024/04/snapinstaapp-431611991-18052706536566334-2497404585363801473-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2980\" src=\"/uploads/2024/04/snapinstaapp-431679968-18052706527566334-7079469251451663623-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Marhaban Ya Ramdhan…nMenyambut bulan suci Ramadhan SMA IT Ishlahul Ummah prabumulih melakukan kegiatan Tarhib dan Pawai Ramadhan di lingkungan sekolah.nKegiatan...', 'publish', 'post', '/uploads/2024/03/at-smait-ishum-prabumulih.webp', 1253, 4, '2024-03-07 15:36:10', 'TARHIB DAN PAWAI RAMADHAN 2024 - SMA IT Ishlahul Ummah', 'Marhaban Ya Ramdhan…nMenyambut bulan suci Ramadhan SMA IT Ishlahul Ummah prabumulih melakukan kegiatan Tarhib dan Pawai Ramadhan di lingkungan sekolah...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (300, 'MUNAQOSAH HADITS KELAS AKHIR 2024', 'munaqosah-hadits-kelas-akhir-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>SMA IT ISHUM News--</strong> Munaqosah Hadits Kelas Akhir (MHKA) adalah program yang dilaksanakan untuk kelas XII pada semester II. Kegiatan ini merupakan salah satu syarat kelulusan dari SMA IT Ishlahul Ummah Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">MHKA pada tahun ini dilaksanakan pada hari Kamis, 29 Februari 2024 yang diikuti oleh seluruh peserta didik kelas XII.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Al-hamdulillah kegiatan ini berjalan dengan lancar dan peserta didik mengikuti dengan baik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Baarokallahu fiikum kepada ananda yang telah mengikuti Munaqosah Hadits Kelas Akhir 2024 SMA IT Ishlahul Ummah Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐ananda Abdurrosyad Fadlillah (17 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Muhammad Candra (15 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Adhipati Ali (20 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Zen Faturrahman (42 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Gusmauw Arepan (15 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Ragil Rizqy Putra (04 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Yunita Andini Amalia (21 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Nisaa Trie Antika (20 Hadits Arba\'in An-Nawawi)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga Istiqomah dalam menjaga hafalannya dan bisa mengaplikasikan dalam kehidupan sehari-hari secara lafdzan wa ma\'nan wa \'amalan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p>n', 'SMA IT ISHUM News-- Munaqosah Hadits Kelas Akhir (MHKA) adalah program yang dilaksanakan untuk kelas XII pada semester II. Kegiatan ini merupakan salah satu sya...', 'publish', 'post', '/uploads/2024/03/snapinstaapp-421773522-18048468199566334-1009039121762798981-n-1080.webp', 1476, 4, '2024-02-29 13:26:55', 'MUNAQOSAH HADITS KELAS AKHIR 2024 - SMA IT Ishlahul Ummah', 'SMA IT ISHUM News-- Munaqosah Hadits Kelas Akhir (MHKA) adalah program yang dilaksanakan untuk kelas XII pada semester II. Kegiatan ini merupakan sala...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (301, 'MUNAQOSAH TAHSIN DAN TAHFIZH QUR\'AN KELAS AKHIR 2024', 'munaqosah-tahsin-dan-tahfizh-quran-kelas-akhir-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Munaqosah Tahsin Dan Tahfizh Quran Kelas Akhir (MTTQKA) adalah program yang dilaksanakan untuk kelas XII pada semester II. Kegiatan ini merupakan salah satu syarat kelulusan dari SMA IT Ishlahul Ummah Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">MTTQKA pada tahun ini dilaksanakan pada hari Senin-Selasa, 26-28 Februari 2024 yang diikuti oleh seluruh peserta didik kelas XII.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Al-hamdulillah kegiatan ini berjalan dengan lancar dan peserta didik mengikuti dengan baik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Baarokallahu fiikum kepada ananda yang telah mengikuti Munaqosah Tahfizh dan Tahsin Qur\'an Kelas Akhir 2024 SMA IT Ishlahul Ummah Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐ananda Abdurrosyad Fadlillah (Juz 30, 29, &amp; 1 (1-61))</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Muhammad Candra (Juz 30,01 (1-76))</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Adhipati Ali (Juz 30,01,02)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Zen Faturrahman (Juz 30,29,28,27)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Gusmauw Arepan (Juz 30,29)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Ragil Rizqy Putra (Juz 30 (An-Nas S.D Al-Fajr)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Yunita Andini Amalia (Juz 30,01 (1-83))</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">💐 Ananda Nisaa Trie Antika (Juz 30)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga Istiqomah dalam menjaga hafalannya dan bisa mengaplikasikan dalam kehidupan sehari-hari secara lafdzan wa ma\'nan wa \'amalan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">🔸🔸🔸🔸</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2969\" src=\"/uploads/2024/04/snapinstaapp-431326585-18052396192566334-2089618461474011434-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2974\" src=\"/uploads/2024/04/snapinstaapp-431510092-18052396183566334-7926316184581577171-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /><img class=\"alignnone size-medium wp-image-2971\" src=\"/uploads/2024/04/snapinstaapp-431335724-18052396174566334-8136657537418815327-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" />  <img class=\"alignnone size-medium wp-image-2973\" src=\"/uploads/2024/04/snapinstaapp-431355006-18052396201566334-7744277213200100499-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /><img class=\"alignnone size-medium wp-image-2970\" src=\"/uploads/2024/04/snapinstaapp-431334777-18052396210566334-7019492557633565494-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" />  <img class=\"alignnone size-medium wp-image-2972\" src=\"/uploads/2024/04/snapinstaapp-431338113-18052396219566334-407909461681672992-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2968\" src=\"/uploads/2024/04/snapinstaapp-431121886-18052396228566334-1502924447866477531-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Munaqosah Tahsin Dan Tahfizh Quran Kelas Akhir (MTTQKA) adalah program yang dilaksanakan untuk kelas XII pada semester II. Kegiatan ini merupakan salah satu sya...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-431510092-18052396183566334-7926316184581577171-n-1080.webp', 1011, 4, '2024-02-29 10:59:39', 'MUNAQOSAH TAHSIN DAN TAHFIZH QUR\'AN KELAS AKHIR 2024 - SMA IT Ishlahul Ummah', 'Munaqosah Tahsin Dan Tahfizh Quran Kelas Akhir (MTTQKA) adalah program yang dilaksanakan untuk kelas XII pada semester II. Kegiatan ini merupakan sala...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (302, 'PERINGATAN ISRA MI\'RAJ 1445H/2024', 'peringatan-isra-miraj-1445h-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Senin, 19 Februari 2024</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Peringatan Isra Mi\'raj 1445H tahun ini cukup meriah dikarenakan kegiatan perlombaan diikuti peserta didik SMP IT Ishum dengan antusias.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dalam peringatan ini dimana siswa SMA seluruhnya menjadi panitia kegiatan, adapun lomba yang diselenggarakan pada kegiatan ini yaitu lomba adzan, lomba karaoke islami, lomba melukis, lomba LCCI dan diawali dengan sirah yang disampaikan oleh Ustadz Agi Gustiawan, S.Pd</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, kegiatan ini dibuka secara langsung oleh Kepala Sekolah Ustadzah Anita Carlyna, S.IP., M.Pd dengan diawali sholawat bersama.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3014\" src=\"/uploads/2024/04/snapinstaapp-428288550-18051117526566334-7826877065575415455-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3015\" src=\"/uploads/2024/04/snapinstaapp-428349439-18051117508566334-6909612374027979665-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3016\" src=\"/uploads/2024/04/snapinstaapp-428331539-18051117490566334-848039879976859594-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3017\" src=\"/uploads/2024/04/snapinstaapp-428336463-18051117478566334-484209559970898111-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Senin, 19 Februari 2024nPeringatan Isra Mi\'raj 1445H tahun ini cukup meriah dikarenakan kegiatan perlombaan diikuti peserta didik SMP IT Ishum dengan antusias.n...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-428462961-18051117451566334-5915217743299279655-n-1080.webp', 667, 4, '2024-02-20 13:08:48', 'PERINGATAN ISRA MI\'RAJ 1445H/2024 - SMA IT Ishlahul Ummah', 'Senin, 19 Februari 2024nPeringatan Isra Mi\'raj 1445H tahun ini cukup meriah dikarenakan kegiatan perlombaan diikuti peserta didik SMP IT Ishum dengan...', NULL, '2026-09-11 15:07:23', '2026-09-12 08:54:25'),
  (303, 'IU TADDABUR 2024', 'iu-taddabur-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Rabu, 07 Februari 2024</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">IU Taddabur merupakan program unggulan baru yang diterapkan di SMA IT Ishlahul Ummah, yang mana kegiatan ini bertujuan menggali potensi anak untuk mengeksplorasi ilmu dengan melihat secara langsung alam sebagai object pembelajarannya.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">IU Taddabur ini program perdana yang dilaksanakan di Sungai Pijar Jaya bertepatan di desa Sungai Duren, Lembak Muara Enim. Kegiatan ini berlangsung satu hari, dengan Tema \"Merawat Lingkungan Membangun Peradaban\". Adapun rangkaian kegiatan ini dengan menguji keasaman air sungai, tinggi rendahnya air sungai, mengidentifikasi mikro dan makroorganisme setempat serta mewawancarai penduduk setempat dalam rangka <em>social research.<br />n</em></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, kegiatan ini sangat berkesan dan menambah pengalaman siswa. Output dari kegiatan ini berupa laporan penelitian yang harus dikerjakan oleh masing-masing kelompok.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2986\" src=\"/uploads/2024/04/snapinstaapp-426809229-18049979539566334-7008238706419157105-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2985\" src=\"/uploads/2024/04/snapinstaapp-426174925-18049979569566334-4787233840964938305-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Rabu, 07 Februari 2024nIU Taddabur merupakan program unggulan baru yang diterapkan di SMA IT Ishlahul Ummah, yang mana kegiatan ini bertujuan menggali potensi a...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-426178614-18049979521566334-3969151918927596474-n-1080.webp', 771, 4, '2024-02-08 11:45:42', 'IU TADDABUR 2024 - SMA IT Ishlahul Ummah', 'Rabu, 07 Februari 2024nIU Taddabur merupakan program unggulan baru yang diterapkan di SMA IT Ishlahul Ummah, yang mana kegiatan ini bertujuan menggali...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (304, 'Ngobar (Ngobrol Bareng) 2024', 'ngobar-ngobrol-bareng-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ngobar Time :)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alias Ngobrol Bareng seru berfaedah, merupakan program lama rasa baru. Baru karena setiap bulan minimal 1x akan ada pemateri ahli di bidangnya yang akan mengisi obrolan ini.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, sekolah sudah bekerjasama dengan Ustadz Zayudi Anwar, M.HI dan Ustadz Harun Rasyid, M.Pd untuk berselang seling mengisi obrolan minimal 1x dalam sebulan setiap hari jumat. Adapun pada pekan-pekan lainnya tetap dibersamai oleh ustadz ustazah di SMA IT Ishlahul Ummah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Obrolan seru ini cukup luas dan berbagai genre. mulai dari sirah nabawiyah, fiqh, aqidah dan muamalah. Sehingga pada kesempatan ini kami juga mengundang siswa SMP IT Ishum untuk join biar ilmu yang diberikan menjangkau lebih luas.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-3008\" src=\"/uploads/2024/04/snapinstaapp-423004455-18048872143566334-3609278114542081066-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-3009\" src=\"/uploads/2024/04/snapinstaapp-422962087-18048872134566334-90349359941098832-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Ngobar Time :)nAlias Ngobrol Bareng seru berfaedah, merupakan program lama rasa baru. Baru karena setiap bulan minimal 1x akan ada pemateri ahli di bidangnya ya...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-423223895-18048872125566334-4589360529432580198-n-1080.webp', 853, 4, '2024-01-28 12:59:37', 'Ngobar (Ngobrol Bareng) 2024 - SMA IT Ishlahul Ummah', 'Ngobar Time :)nAlias Ngobrol Bareng seru berfaedah, merupakan program lama rasa baru. Baru karena setiap bulan minimal 1x akan ada pemateri ahli di bi...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (305, 'BBM (Belajar Bersama Maestro) 2024', 'bbm-belajar-bersama-maestro-2024', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kamis, 25 Januari 2024</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Belajar Bersama Maestro atau dikenal dengan singkatan BBM yang merupakan salah satu program unggulan di tahun 2024 ini. Kegiatan ini mengajak wali murid untuk berpartisipasi langsung dalam memberikan wawasan keilmuan sesuai dengan profesi mereka masing-masing.<br />nBBM ini juga pernah dilakukan pada tahun lalu namun dengan penamaan yang berbeda yaitu Parents Teaching, namun dengan konsep yang kurang lebih sama.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">BBM kali ini kita mengundang wali murid yang berprofesi sebagai pengusaha rempah-rempah olahan atau bumbu dapur. Tujuan kegiatan ini agar siswa mengenal rempah-rempah Indonesia yang diperjualbelikan di pasaran serta fungsi dari masing-masing rempah tersebut sampai ke tahap pengolahan rempah menjadi bumbu dasar olahan masak ataupun obat-obatan tradisional.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini diikuti seluruh kelas X dan XI, di ruang AL-Quds dan dibuka secara langsung oleh Kepala Sekolah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2998\" src=\"/uploads/2024/04/snapinstaapp-421764485-18048653680566334-6733977746318470608-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2997\" src=\"/uploads/2024/04/snapinstaapp-422271889-18048653689566334-2441896534895904104-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2996\" src=\"/uploads/2024/04/snapinstaapp-421787909-18048653653566334-2375362677475301477-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Kamis, 25 Januari 2024nBelajar Bersama Maestro atau dikenal dengan singkatan BBM yang merupakan salah satu program unggulan di tahun 2024 ini. Kegiatan ini meng...', 'publish', 'post', '/uploads/2024/04/snapinstaapp-421794121-18048653713566334-8666163768545332372-n-1080.webp', 883, 4, '2024-01-26 12:00:15', 'BBM (Belajar Bersama Maestro) 2024 - SMA IT Ishlahul Ummah', 'Kamis, 25 Januari 2024nBelajar Bersama Maestro atau dikenal dengan singkatan BBM yang merupakan salah satu program unggulan di tahun 2024 ini. Kegiata...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (306, 'Literasi Sekolah', 'literasi-sekolah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT Ishlahul Ummah (SMA IT ISHUM) Prabumulih</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Literasi Sekolah (LS) adalah kemampuan mengakses, memahami, dan menggunakan sesuatu secara cerdas melalui berbagai aktivitas, antara lain membaca, melihat, menyimak, menulis, dan/ atau berbicara. LS merupakan sebuah upaya yang dilakukan secara menyeluruh untuk menjadikan sekolah sebagai organisasi pembelajaran yang warganya literat sepanjang hayat melalui pelibatan publik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun tujuannya untuk menumbuhkembangkan budi pekerti peserta didik melalui pembudayaan ekosistem literasi sekolah yang diwujudkan dalam Gerakan Literasi Sekolah agar mereka menjadi pembelajar sepanjang hayat. Selain itu bertujuan juga agar menumbuhkembangkan budaya literasi di sekolah; meningkatkan kapasitas warga dan lingkungan sekolah agar literat; menjadikan sekolah sebagai taman belajar yang menyenangkan dan ramah anak agar warga sekolah mampu mengelola pengetahuan; menjaga keberlanjutan pembelajaran dengan menghadirkan beragam buku bacaan dan mewadahi berbagai strategi membaca.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT ISHUM Prabumulih melaksanakan kegiatan LS dimulai pada Senin, 22 Januari 2024 yang diikuti seluruh peserta didik dan guru. Kegiatan ini dilaksanakan setiap pagi hari sebelum belajar selama 15 menit. Kegiatan ini dilaksanakan karena minat baca peserta didik sangat rendah maka melalui kegiatan LS ini menjadi wadah untuk menumbuhkan minat peserta didik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun kegiatan ini dilaksanakan dengan metode sebagai berikut :</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pekan pertama</p><ol><li>10 menit diawal membaca senyap mandiri</li><li>Kemudian 5 menit akhir salah satu siswa menyimpulkan hasil bacaannya</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pekan kedua</p><ol><li>10 menit diawal salah satu siswa membaca nyaring di depan kelas</li><li>kemudian 5 menit akhir salah satu yg mendengarkan untuk menyimpulkan apa yang sudah didengarkan</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pekan ketiga</p><ol><li>10 menit diawal membaca senyap mandiri</li><li>Kemudian 5 menit akhir menyimpulkan bacaan dengan menuliskannya dalam bentuk syair/essay/puisi dll</li>n</ol><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dan untuk pekan selanjutnya kembali ke awal</p><h2><img class=\"alignnone  wp-image-2965\" src=\"/uploads/2024/03/snapinstaapp-422193031-18048468163566334-5823808780842588355-n-1080-300x300.webp\" alt=\"\" width=\"197\" height=\"197\" /><img class=\"alignnone  wp-image-2962\" src=\"/uploads/2024/03/snapinstaapp-421723702-18048468190566334-7931432694195479362-n-1080-300x300.webp\" alt=\"\" width=\"201\" height=\"201\" data-wp-editing=\"1\" /></h2><h5><img class=\"alignnone  wp-image-2961\" src=\"/uploads/2024/03/snapinstaapp-421715887-18048468172566334-3670518987277757971-n-1080-300x300.webp\" alt=\"\" width=\"205\" height=\"205\" />  <img class=\"alignnone  wp-image-2963\" src=\"/uploads/2024/03/snapinstaapp-421773522-18048468199566334-1009039121762798981-n-1080-300x300.webp\" alt=\"\" width=\"208\" height=\"208\" /> <img class=\"alignnone  wp-image-2964\" src=\"/uploads/2024/03/snapinstaapp-421773765-18048468181566334-5234613695284888337-n-1080-300x300.webp\" alt=\"\" width=\"212\" height=\"212\" /></h5>n', 'SMA IT Ishlahul Ummah (SMA IT ISHUM) PrabumulihnLiterasi Sekolah (LS) adalah kemampuan mengakses, memahami, dan menggunakan sesuatu secara cerdas melalui berbag...', 'publish', 'post', '/uploads/2024/03/snapinstaapp-421773765-18048468181566334-5234613695284888337-n-1080.webp', 1373, 4, '2024-01-22 08:00:11', 'Literasi Sekolah - SMA IT Ishlahul Ummah', 'SMA IT Ishlahul Ummah (SMA IT ISHUM) PrabumulihnLiterasi Sekolah (LS) adalah kemampuan mengakses, memahami, dan menggunakan sesuatu secara cerdas mela...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (307, 'RAPAT KOMITE DAN PEMBERIAN SERTIFIKAT MUNAQOSAH TAHSIN DAN TAHFIZH QUR\'AN', 'rapat-komite-dan-pemberian-sertifikat-munaqosah-tahsin-dan-tahfizh-quran', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Prabumulih - Jumat, 17 Desember 2023</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Forum Orang tua Murid dan Guru (FOMG)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini dihadiri oleh seluruh Orang Tua Murid dari kelas 10, 11, 12 dan Semua Guru. Kegiatan ini dilakukan secara Offline. Perhatian Penuh Orang Tua terhadap tumbuh dan kembang Siwa dalam masa Pendidikan SMA adalah hal penting dan utama.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Keberhasilan Guru untuk dapat medidik dan membina secara tepat dan benar kepada siswa tidak akan optimal saat peranan Orang Tua Murid tidak terbangun baik dengan Guru. Persatuan Orang Tua Murid menjadi Wadah yang tepat dalam ruang saling bersilahturahmi dan berdiskusi dalam perkembangan Siswa.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini pun diagendakan sekali dalam semester sebagai bentuk keseriusan pihak Sekolah dalam benar-benar sebagai mitra keluarga membentuk generasi Sholeh dan solehah.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">pada kegiatan ini pun pemberian penghargaan kepada siswa berprestasi yakni :<br />n1. Ananda Zen Fathurrahman ( 3 Juz-Jayyid Jiddan)<br />n2. ⁠Ananda Alief Rasya Arrafi ( 3 Juz-Jayyid Jiddan)<br />n3. ⁠Ananda M. Abi Khatim Al Habsy Lubis (3 Juz-Jayyid)<br />n4. ⁠Ananda Nisaa Trie Antika (1 Juz-Jayyid)<br />n5. Ananda Muhammad Sayyid Tsaqif (Tahsin level 3)<br />n6. ⁠Ananda Toby Aldinata Timothy (Tahsin level 3)<br />n7. Ananda M. Naufal Rohmattullah (Tahsin level 2)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Barakallahu fiikum ananda sholih dan sholiha 🤲</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Teruslah berproses, bertumbuh menjadi pribadi yang lebih baik lagi dan semangat mengukir prestasi ✊️</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Investasi jangka panjang yang tak ternilai harganya baik di dunia maupun akhirat ialah anak yang shalih dan shalihah</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2952\" src=\"/uploads/2024/01/snapinstaapp-411254210-18044175475566334-3947523929716609532-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /><img class=\"alignnone size-medium wp-image-2953\" src=\"/uploads/2024/01/snapinstaapp-411292224-18044175466566334-3480095105572502639-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2949\" src=\"/uploads/2024/01/snapinstaapp-411225083-18044175448566334-1580509847810048900-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2950\" src=\"/uploads/2024/01/snapinstaapp-411230380-18044175406566334-8527218528719033928-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2951\" src=\"/uploads/2024/01/snapinstaapp-411252046-18044175397566334-6942874359018038142-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" />   <img class=\"alignnone size-medium wp-image-2954\" src=\"/uploads/2024/01/snapinstaapp-411292350-18044175415566334-154472812246161421-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2955\" src=\"/uploads/2024/01/snapinstaapp-411310177-18044175436566334-5092343811737369353-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Prabumulih - Jumat, 17 Desember 2023nForum Orang tua Murid dan Guru (FOMG)nKegiatan ini dihadiri oleh seluruh Orang Tua Murid dari kelas 10, 11, 12 dan Semua Gu...', 'publish', 'post', '/uploads/2024/01/snapinstaapp-411252046-18044175397566334-6942874359018038142-n-1080.webp', 1114, 4, '2024-01-04 13:57:30', 'RAPAT KOMITE DAN PEMBERIAN SERTIFIKAT MUNAQOSAH TAHSIN DAN TAHFIZH QUR\'AN - SMA IT Ishlahul Ummah', 'Prabumulih - Jumat, 17 Desember 2023nForum Orang tua Murid dan Guru (FOMG)nKegiatan ini dihadiri oleh seluruh Orang Tua Murid dari kelas 10, 11, 12 da...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (308, '1 MUHARRAM 1445 H', '1-muharram-1445-h', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Dalam Rangka menyambut Tahun Baru Islam, SIT Ishlahul Ummah dari TK s.d SMA melakukan giat berbagi sesama untuk mereka yang membutuhkan khususnya anak-anak yatim di sekitar kita.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2751\" src=\"/uploads/2023/10/snapinstaapp-361647401-1484923105585350-2797377786340784626-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2752\" src=\"/uploads/2023/10/snapinstaapp-361763354-1552538385554617-4357943548146905446-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /> <img class=\"alignnone size-medium wp-image-2753\" src=\"/uploads/2023/10/snapinstaapp-361924390-3571161743118666-847923446244712120-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /><img class=\"alignnone size-medium wp-image-2750\" src=\"/uploads/2023/10/snapinstaapp-361376839-980474209858395-7654269247104231061-n-1080-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /><br />nBarakallahu fiikum, semoga yang memberi dan yang diberi mendapatkan RidhoNya Aamiin</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Berbagi kebahagiaan, mengasihi dan saling menyayangi antar sesama merupakan wujud nyata perilaku umat Islam yang sesungguhnya. Semoga kita semua bisa mengikuti sunah-sunah Rasulullah dan mendapat syafaatNya 🤗😍🌱</p>n', 'Dalam Rangka menyambut Tahun Baru Islam, SIT Ishlahul Ummah dari TK s.d SMA melakukan giat berbagi sesama untuk mereka yang membutuhkan khususnya anak-anak yati...', 'publish', 'post', '/uploads/2023/10/snapinstaapp-361116580-259033736882734-4449034481999193349-n-1080.webp', 608, 4, '2023-10-12 14:12:30', '1 MUHARRAM 1445 H - SMA IT Ishlahul Ummah', 'Dalam Rangka menyambut Tahun Baru Islam, SIT Ishlahul Ummah dari TK s.d SMA melakukan giat berbagi sesama untuk mereka yang membutuhkan khususnya anak...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (309, '[Hari Raya Idul Adha 1444 H]', 'hari-raya-idul-adha-1444-h', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Idul Adha dinamai juga “Idul Nahr” artinya hari raya penyembelihan. Hal ini untuk memperingati ujian paling berat yang menimpa Nabi Ibrahim. Akibat dari kesabaran dan ketabahan Ibrahim dalam menghadapi berbagai ujian dan cobaan, Allah memberinya sebuah anugerah, sebuah kehormatan “Khalilullah” (kekasih Allah).<br />nSumber : jabar.kemenag.go.id</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Keluarga Besar SMA IT Ishlahul Ummah Prabumulih Mengucapkan</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Selamat Hari Raya Idul Adha 1444 H 😇🙏</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">\"Sesungguhnya Kami telah memberimu (Nabi Muhammad) nikmat yang banyak. Maka, laksanakanlah salat karena Tuhanmu dan berkurbanlah!\" (Qs. Al-Kautsar : 1-2)</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><img class=\"alignnone size-medium wp-image-2733\" src=\"/uploads/2023/10/snapinstaapp-356266366-122720224189478-5952045886615671413-n-1024-300x300.webp\" alt=\"\" width=\"300\" height=\"300\" /></p>n', 'Idul Adha dinamai juga “Idul Nahr” artinya hari raya penyembelihan. Hal ini untuk memperingati ujian paling berat yang menimpa Nabi Ibrahim. Akibat dari kesabar...', 'publish', 'post', '/uploads/2023/10/snapinstaapp-356266366-122720224189478-5952045886615671413-n-1024.webp', 969, 4, '2023-10-12 13:57:22', '[Hari Raya Idul Adha 1444 H] - SMA IT Ishlahul Ummah', 'Idul Adha dinamai juga “Idul Nahr” artinya hari raya penyembelihan. Hal ini untuk memperingati ujian paling berat yang menimpa Nabi Ibrahim. Akibat da...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (310, 'PROJECT SOCIAL (Menyantuni Anak Yatim)', 'project-social-menyantuni-anak-yatim', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Peringatan Tahun Baru Islam 1445 h/2023 m SMA IT Ishlahul Ummah Prabumulih, dilaksanakan pada hari Rabu, 26 Juli 2023, dimulai pukul 13.30 sampai dengam 15.00. kegiatan ini dilaksanakan selama satu hari dan dengan dilaksanakan secara ofline, Tempat pelaksanaan kegiatan ini dilakukan di dua tempat yakni :</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">1. Rumah panti asuhan wahdini sukajadi</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">2. Rumah panti asuhan Darul Qur\'an patih galung prabumulih barat.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan ini juga diikuti oleh seluruh Peserta didik SMA IT Ishlahul Ummah Prabumulih. Jumlah keseluruhan peserta yang mengikuti kegiatan ini berjumlah 20 peserta didik.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Adapun narasumber dan fasilitator dalam kegiatan ini terdiri dari</p><ul><li>Narasumber : Pengasuh atau ketua panti asuhan</li><li>Fasilitator : Semua pegawai panti asuhan yang ada</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Semoga melalui kegiatan ini peserta didik dapat mengambil pelajaran terkait kepedulian terhadap sesama ummat muslim.</p>n', 'Peringatan Tahun Baru Islam 1445 h/2023 m SMA IT Ishlahul Ummah Prabumulih, dilaksanakan pada hari Rabu, 26 Juli 2023, dimulai pukul 13.30 sampai dengam 15.00....', 'publish', 'post', '/uploads/campus-robbani.webp', 1692, 4, '2023-07-26 14:21:09', 'PROJECT SOCIAL (Menyantuni Anak Yatim) - SMA IT Ishlahul Ummah', 'Peringatan Tahun Baru Islam 1445 h/2023 m SMA IT Ishlahul Ummah Prabumulih, dilaksanakan pada hari Rabu, 26 Juli 2023, dimulai pukul 13.30 sampai deng...', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (311, 'Day--5 MPLS', 'day-5-mpls', 'rnrnrn[Khutbah Jum\'at]rnrnHari ini, jum\'at (21/7) salah satu peserta didik SMA IT Ishlahul Ummah telah melaksanakan khutbah jum\'at di masjid SIT Ishlahul Ummah.rnrn👳 Khotib Jum\'at :rnAnanda M. Abi Khatim Al Habsy Lubis (XI. Al-Quds)rnrnSemoga menjadi bekal nanti ketika terjun ke masyarakat🤲🤲🤲rnrn_______________rn<a class=\"x1i10hfl xjbqb8w x6umtig x1b1mbwd xaqea5y xav7gou x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" tabindex=\"0\" role=\"link\" href=\"https://www.instagram.com/explore/tags/jum/\">#jum</a>\'atberkah <a class=\"x1i10hfl xjbqb8w x6umtig x1b1mbwd xaqea5y xav7gou x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" tabindex=\"0\" role=\"link\" href=\"https://www.instagram.com/explore/tags/jum/\">#jum</a>\'atsejahtera <a class=\"x1i10hfl xjbqb8w x6umtig x1b1mbwd xaqea5y xav7gou x9f619 x1ypdohk xt0psk2 xe8uvvx xdj266r x11i5rnm xat24cr x1mh8g0r xexx8yu x4uap5 x18d9i69 xkhd6sd x16tdsg8 x1hl2dhg xggy1nq x1a2a7pz  _aa9_ _a6hd\" tabindex=\"0\" role=\"link\" href=\"https://www.instagram.com/explore/tags/khotibjum/\">#khotibjum</a>\'atrnrnYuk ikuti kami disini 👇rn🏢 SMA IT Ishlahul Ummah Prabumulihrnrn🟢 Tiktok-Facebook-Youtubernsmait_ishum_prabumulihrnrn🟢Websiternsmaitishumpbm.sch.idrnrn🟢EmailrnSmaitishlahulummah2019@gmail.comrnrn🟢AlamatrnJl. Sadewa RT 01 RW 04 Kel. Karang Raja Kec. Prabumulih Timurrnrn🟢Cp WA Admin SMAITrn0821-8268-0647', 'rnrnrn[Khutbah Jum\'at]rnrnHari ini, jum\'at (21/7) salah satu peserta didik SMA IT Ishlahul Ummah telah me...', 'publish', 'post', '/uploads/2023/10/snapinstaapp-361778841-956094075651112-5227493163692866355-n-1080.webp', 174, 4, '2023-07-21 12:43:00', 'Day--5 MPLS - SMA IT Ishlahul Ummah', '[gallery ids=\"2829,2828,2827,2826,2825,2824,2823,2822\"]rnrnrn[Khutbah Jum\'at]rnrnHari ini, jum\'at 