  (353, 'Prestasi Siswa: Juara 1 MHQ (Juz 30) (Juara 1 Tingkat Kota)', 'prestasi-juara-1-mhq-juz-30', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Juara 1 MHQ (Juz 30) (Juara 1) dalam ajang yang diselenggarakan oleh Akademi Da\'wah Kota Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ajang ini diselenggarakan pada tahun 08.00 tingkat Kota. Semoga capaian membanggakan ini menjadi motivasi bagi seluruh santri SMA IT Ishum Prabumulih untuk terus berprestasi dan berakhlak mulia.</p>', 'Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Juara 1 MHQ (Juz 30) (Juara 1) dalam ajang yang diselenggarakan oleh Akademi Da\'wah Kota Prabumulih.', 'publish', 'post', '/uploads/ishum/prestasi_3656_41_20250108_141948_0004.webp', 562, NULL, '2024-05-10 10:00:00', NULL, NULL, NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (354, 'Prestasi Siswa: Juara 1 MTQ (Cabang 30 Juz) (Juara 1 Tingkat Kota)', 'prestasi-juara-1-mtq-cabang-30-juz', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Juara 1 MTQ (Cabang 30 Juz) (Juara 1) dalam ajang yang diselenggarakan oleh LPTQ Prabumulih.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ajang ini diselenggarakan pada tahun  tingkat Kota. Semoga capaian membanggakan ini menjadi motivasi bagi seluruh santri SMA IT Ishum Prabumulih untuk terus berprestasi dan berakhlak mulia.</p>', 'Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Juara 1 MTQ (Cabang 30 Juz) (Juara 1) dalam ajang yang diselenggarakan oleh LPTQ Prabumulih.', 'publish', 'post', '/uploads/ishum/prestasi_3658_19_20250108_141947_0000.webp', 340, NULL, '2024-05-10 10:00:00', NULL, NULL, NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25');
