  (355, 'Prestasi Siswa: Juara 2 MHQ (Juara 2 Tingkat Provinsi Sumatera Selatan)', 'prestasi-juara-2-mhq', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Juara 2 MHQ (Juara 2) dalam ajang yang diselenggarakan oleh JSIT Wilayah Sumatera Selatan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ajang ini diselenggarakan pada tahun  tingkat Provinsi Sumatera Selatan. Semoga capaian membanggakan ini menjadi motivasi bagi seluruh santri SMA IT Ishum Prabumulih untuk terus berprestasi dan berakhlak mulia.</p>', 'Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Juara 2 MHQ (Juara 2) dalam ajang yang diselenggarakan oleh JSIT Wilayah Sumatera Selatan.', 'publish', 'post', '/uploads/ishum/prestasi_3660_31_20250108_141948_0002.webp', 1086, NULL, '2024-05-10 10:00:00', NULL, NULL, NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (356, 'Prestasi Siswa: Setoran Hafalan 30 Juz Riwayat Hafsh ( Tingkat )', 'prestasi-setoran-hafalan-30-juz-riwayat-hafsh', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Setoran Hafalan 30 Juz Riwayat Hafsh () dalam ajang yang diselenggarakan oleh .</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ajang ini diselenggarakan pada tahun  tingkat . Semoga capaian membanggakan ini menjadi motivasi bagi seluruh santri SMA IT Ishum Prabumulih untuk terus berprestasi dan berakhlak mulia.</p>', 'Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Setoran Hafalan 30 Juz Riwayat Hafsh () dalam ajang yang diselenggarakan oleh .', 'publish', 'post', '/uploads/ishum/prestasi_3811_Feed-IG-smait_20250326_132427_0000.webp', 610, NULL, '2024-05-10 10:00:00', NULL, NULL, NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (357, 'Prestasi Siswa: Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta ( Tingkat )', 'prestasi-beasiswa-hafizah-hafizh-pendidikan-kedokteran-uii-yogyakarta', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta () dalam ajang yang diselenggarakan oleh .</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ajang ini diselenggarakan pada tahun  tingkat . Semoga capaian membanggakan ini menjadi motivasi bagi seluruh santri SMA IT Ishum Prabumulih untuk terus berprestasi dan berakhlak mulia.</p>', 'Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta () dalam ajang yang diselenggarakan oleh .', 'publish', 'post', '/uploads/ishum/prestasi_3813_PPDB-SMAIT-ISHUM-21-x-29.7-cm-1080-x-1350-piksel_20250330_144819_0000.webp', 414, NULL, '2024-05-10 10:00:00', NULL, NULL, NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (358, 'Prestasi Siswa: Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an (Juara 3 Tingkat Provinsi Sumatera Selatan)', 'prestasi-3823', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an (Juara 3) dalam ajang yang diselenggarakan oleh LPTQ Sumsel.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Ajang ini diselenggarakan pada tahun  tingkat Provinsi Sumatera Selatan. Semoga capaian membanggakan ini menjadi motivasi bagi seluruh santri SMA IT Ishum Prabumulih untuk terus berprestasi dan berakhlak mulia.</p>', 'Alhamdulillah, siswa SMA IT Ishlahul Ummah Prabumulih berhasil meraih prestasi Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an (Juara 3) dalam ajang yang diselenggarakan oleh LPTQ Sumsel.', 'publish', 'post', '/uploads/ishum/prestasi_3823_IMG-20250428-WA0115-scaled.webp', 392, NULL, '2024-05-10 10:00:00', NULL, NULL, NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (359, 'Sambutan Kepala Sekolah', 'sambutan-kepala-sekolah', '<p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Selamat datang (ahlan wa sahlan) di website resmi SMA IT Ishlahul Ummah Prabumulih</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Segala puji hanya untuk Allah SWT atas segala nikmat, karunia dan hidayahNya. Sholawat serta salam semoga tercurahkan kepada suri tauladan kita umat islam Muhammad Rasulullah SAW, serta para sahabat, keluarga dan pengikutnya yang setia hingga akhir zaman.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Generasi z tak lepas dari perkembangan teknologi yang pesat. Segenap civitas akademik harus bisa beradaptasi dengan segala perubahan salah satunya dengan kewajiban lembaga untuk membuat website sekolah. Alhamdulillah dengan adanya website ini semoga dapat memudahkan ayah bunda, saudara/i mengeksplor SMA IT Ishlahul Ummah lebih dekat dan lebih akurat.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Terimakasih kepada semua pihak yang telah mendukung terutama Ust. H. Mat Amin, S.Ag selaku pembina Yayasan Ishlahul Ummah dan Ummi TL. Fasmawati, S. Ag selaku Ketua Yayasan Ishlahul Ummah Prabumulih serta para dewan guru, karyawan, sahabat ishum dimanapun berada. Semoga layanan website kami dapat bermanfaat dan membantu pengunjung sekalian mendapatkan informasi yang kalian inginkan. Kritik dan saran kami harapkan untuk kemajuan SMA IT Ishlahul Ummah Prabumulih.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Salam mendidik sepenuh cinta.</p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\"><strong>Kepala SMA IT Ishlahul Ummah</strong></p><p class=\"ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\"><strong>Agi Gustiawan, S. Pd</strong></p>', 'Sambutan resmi Kepala Sekolah SMA IT Ishlahul Ummah Prabumulih, Agi Gustiawan, S. Pd.', 'publish', 'page', '/uploads/kepsek-agi-gustiawan.webp', '0', 4, '2026-09-12 07:03:45', 'Sambutan Kepala Sekolah - SMA IT Ishlahul Ummah Prabumulih', 'Pesan dan komitmen pembinaan karakter, iman, dan ilmu di SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (360, 'Visi dan Misi', 'visi-dan-misi', '<div class=\"mb-6\"><h3 class=\"text-xl font-bold text-[#00913e] mb-3\">Visi Sekolah</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>“TERWUJUDNYA PESERTA DIDIK YANG TANGGAP, TANGKAS DAN TANGGUH DALAM RANGKA PERBAIKAN UMAT MENUJU INDONESIA EMAS”</strong></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong> </strong></p>n</div><div><h3 class=\"text-xl font-bold text-[#00913e] mb-3\">Misi Sekolah</h3><ul><li>Menanamkan peserta didik akhlak mulia dan cara pandang kehidupan yang islami.</li><li>Melatih peserta didik untuk terlibat dalam memperbaiki permasalahan di masyarakat</li><li>Menanamkan komitmen dan tanggung jawab dalam menjalankan perannya di</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>TUJUAN :</strong></p><ul><li>Mempunyai aqidah yang lurus dan melaksanakan ibadah/kebaikan dengan kesadaran serta tanggung jawab</li><li>Mampu membaca Al-Quran dengan tartil serta menghafal dengan mutqin</li><li>Terbiasa bersikap santun, berakhlak mulia, berpikir kritis, mandiri dan kreatif</li><li>Berprestasi dalam kompetisi tingkat nasional</li><li>Mampu beradaptasi dengan perkembangan IPTEK dan IMTAQ</li><li>Menjadi penggerak dalam kebaikan di masyarakat.</li>n</ul><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">&nbsp;</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>SEJARAH :</strong></p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT ISHLAHUL UMMAH PRABUMULIH berdiri pada tanggal 19 Januari 2019, yang di prakarsai oleh H. Mat Amin, S.Ag selaku Pembina Yayasan dan Hj. TL. Fasmawati, S.Ag selaku Ketua Yayasan Ishlahul Ummah Prabumulih. SMA pertama dan satu-satunya yang tergabung bersama JSIT (Jaringan Sekolah Islam Terpadu) di Kota Prabumulih.<br />nTahun pertama SMA IT Ishlahul Ummah Prabumulih dipimpin oleh Ustadzah Mulyani Rahayu, S.T., M.Pd yang mana juga memegang amanah sebagai Kepala SMP IT Ishlahul Ummah dan berlangsung hingga tahun kedua. Tahun ketiga hingga saat ini, SMA IT Ishlahul Ummah Prabumulih dipimpin oleh Ustadzah Anita Carlyna, S.IP., M.Pd.</p>n</div>', 'Visi & Misi resmi SMA IT Ishlahul Ummah Prabumulih menuju generasi emas tanggap, tangkas, dan tangguh.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', 4, '2026-09-12 07:03:45', 'Visi dan Misi - SMA IT Ishlahul Ummah Prabumulih', 'Visi dan Misi pendidikan Islam terpadu SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (361, 'Tentang Kami', 'tentang-kami', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT Ishlahul Ummah Prabumulih adalah Sekolah Menengah Atas Islam Terpadu pertama di Kota Prabumulih yang berada di bawah naungan Yayasan Ishlahul Ummah dan tergabung dalam Jaringan Sekolah Islam Terpadu (JSIT) Indonesia.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sekolah kami memadukan kurikulum nasional dan kurikulum keislaman khas JSIT yang menekankan pada pembentukan akidah salimah, ibadah shahihah, akhlak karimah, kemampuan tahfidz Al-Qur\'an, kepemimpinan, dan keunggulan akademik sains serta teknologi.</p>', 'Profil singkat SMA IT Ishlahul Ummah Prabumulih: Kurikulum terpadu JSIT dan Kurikulum Merdeka.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', 4, '2026-09-12 07:03:45', 'Tentang Kami - SMA IT Ishlahul Ummah Prabumulih', 'Profil SMA IT Ishlahul Ummah Prabumulih, sekolah Islam terpadu di Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (362, 'Sejarah Singkat', 'sejarah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">SMA IT Ishlahul Ummah Prabumulih didirikan atas aspirasi masyarakat muslim di Prabumulih yang mendambakan kelanjutan pendidikan Islam terpadu setelah jenjang SMP IT. Dengan izin operasional resmi nomor 0876/DPMPTSP.V/IX/2023 dan SK Pendirian 2.16.72.04.001 tertanggal 23 Oktober 2020, sekolah ini terus berkembang pesat menjadi institusi pendidikan unggulan di Sumatera Selatan.</p>', 'Sejarah berdirinya SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', 4, '2026-09-12 07:03:45', 'Sejarah - SMA IT Ishlahul Ummah Prabumulih', 'Sejarah perjalanan pendirian SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (363, 'Struktur Organisasi', 'struktur-organisasi', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Struktur kepemimpinan dan manajemen SMA IT Ishlahul Ummah Prabumulih dipimpin oleh Kepala Sekolah Agi Gustiawan, S.Pd, didampingi oleh Wakil Kepala Sekolah Bidang Kurikulum Anita Carlyna, S.IP., M.Pd, serta staf pendidik dan tenaga kependidikan profesional.</p>', 'Bagan susunan struktur pimpinan dan manajemen SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', 4, '2026-09-12 07:03:45', 'Struktur Organisasi - SMA IT Ishlahul Ummah Prabumulih', 'Susunan pimpinan dan tata kelola SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (364, 'Infaq & Wakaf Pembangunan SMA IT Ishlahul Ummah', 'donasi', '<h3>Investasi Akhirat Melalui Pendidikan Islam</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Yayasan Ishlahul Ummah Prabumulih membuka kesempatan seluas-luasnya bagi kaum muslimin dan para dermawan untuk menyalurkan infaq dan sedekah jariyah. Dana yang terhimpun disalurkan untuk pembangunan sarana laboratorium, mushola, ruang kelas baru, dan beasiswa pendidikan santri berprestasi.</p>', 'Salurkan infaq dan wakaf terbaik Anda untuk sarana pendidikan Islam dan beasiswa tahfidz di Kota Prabumulih.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', NULL, NULL, 'Infaq & Wakaf Pembangunan SMA IT Ishlahul Ummah', 'Salurkan infaq dan wakaf terbaik Anda untuk sarana pendidikan Islam dan beasiswa tahfidz di Kota Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (365, 'E-Library & Modul Pembelajaran SMA IT Ishum', 'e-book', '<h3>Pusat E-Library & Buku Digital</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Daftar koleksi buku pelajaran Kurikulum Merdeka, modul guru, dan bacaan islami yang dapat diakses dan diunduh oleh civitas akademika SMA IT Ishlahul Ummah Prabumulih.</p>', 'Kumpulan buku pelajaran, panduan kurikulum, dan modul e-library santri SMA IT Ishum.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', NULL, NULL, 'E-Library & Modul Pembelajaran SMA IT Ishum', 'Kumpulan buku pelajaran, panduan kurikulum, dan modul e-library santri SMA IT Ishum.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (366, 'Mars & Hymne Jaringan Sekolah Islam Terpadu', 'hymne-mars', '<h3>Mars JSIT Indonesia</h3><p class=\"italic text-gray-600 ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Membina tunas bangsa, beriman dan bertaqwa, cerdas berakhlak mulia...</p>', 'Lagu mars dan hymne Sekolah Islam Terpadu kebanggaan SMA IT Ishlahul Ummah.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', NULL, NULL, 'Mars & Hymne Jaringan Sekolah Islam Terpadu', 'Lagu mars dan hymne Sekolah Islam Terpadu kebanggaan SMA IT Ishlahul Ummah.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (367, 'Logo Resmi SMA IT Ishlahul Ummah Prabumulih', 'logo', '<h3>Filosofi Logo SMA IT Ishlahul Ummah</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Logo SMA Islam Terpadu Ishlahul Ummah Prabumulih memadukan lambang perisai keimanan, kubah masjid, Al-Qur\'an terbuka, dan obor semangat dengan skema warna dominan hijau Islami dan merah yang melambangkan keberanian, ketangguhan, serta cita-cita luhur menuju perbaikan umat.</p>', 'Makna filosofis lambang dan logo resmi SMA Islam Terpadu Ishlahul Ummah Prabumulih.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', NULL, NULL, 'Logo Resmi SMA IT Ishlahul Ummah Prabumulih', 'Makna filosofis lambang dan logo resmi SMA Islam Terpadu Ishlahul Ummah Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (368, 'Kontak & Sekretariat PPDB SMA IT Ishum', 'hubungi', '<h3>Sekretariat Sekolah & Panitia PPDB</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Silakan kunjungi kampus kami atau hubungi panitia PPDB untuk informasi pendaftaran peserta didik baru, jadwal seleksi, dan beasiswa.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>Alamat:</strong> Jalan Sadewa RT 01 RW 03 Kel. Karang Raja, Kec. Prabumulih Timur, Kota Prabumulih, Sumatera Selatan 31111.<br><strong>WhatsApp / Telp:</strong> 0821-8268-0647<br><strong>Email:</strong> smaitishlahulummah2019@gmail.com</p>', 'Alamat dan kontak resmi sekretariat SMA Islam Terpadu Ishlahul Ummah Prabumulih.', 'publish', 'page', '/uploads/logo-ishum.webp', '0', NULL, NULL, 'Kontak & Sekretariat PPDB SMA IT Ishum', 'Alamat dan kontak resmi sekretariat SMA Islam Terpadu Ishlahul Ummah Prabumulih.', NULL, '2026-09-11 15:07:24', '2026-09-12 08:54:25'),
  (369, 'Kontak & Lokasi', 'kontak', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Silakan hubungi kami atau kunjungi kampus SMA IT Ishlahul Ummah Prabumulih di Jalan Sadewa RT 01 RW 03 Kelurahan Karang Raja Kecamatan Prabumulih Timur Kota Prabumulih.</p>', 'Kontak resmi, telepon, WhatsApp, email, dan alamat SMA IT Ishlahul Ummah.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'Kontak Kami - SMA IT Ishlahul Ummah Prabumulih', 'Hubungi SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (370, 'Layanan Terpadu', 'layanan-terpadu-2', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Layanan Terpadu SMA IT Ishlahul Ummah Prabumulih melayani berbagai permohonan administrasi secara transparan dan mudah, antara lain:</p><ul><li><strong>Permohonan Izin Kunjungan ke Sekolah:</strong> Pengajuan kunjungan edukatif, studi banding, atau instansi.</li><li><strong>Permohonan Kerja Sama:</strong> Kemitraan lembaga, magang, beasiswa, dan sponsorship.</li><li><strong>Permohonan Sewa Menyewa Barang / Fasilitas:</strong> Penyewaan aula, sarana olahraga, dan fasilitas sekolah.</li></ul>', 'Layanan administrasi terpadu SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'Layanan Terpadu - SMA IT Ishlahul Ummah Prabumulih', 'Portal permohonan dan layanan terpadu SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (371, 'Permohonan Izin Kunjungan ke Sekolah', 'izin-sekolah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Formulir dan prosedur permohonan izin kunjungan edukasi, studi banding, atau observasi ke SMA IT Ishlahul Ummah Prabumulih.</p>', 'Permohonan Izin Kunjungan ke Sekolah.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'Permohonan Izin Kunjungan - SMA IT Ishlahul Ummah', 'Pengajuan izin kunjungan resmi ke SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (372, 'Permohonan Kerja Sama', 'permohonan-kerja-sama', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Layanan resmi permohonan kemitraan, kerjasama kelembagaan, dan kegiatan kolaboratif bersama SMA IT Ishlahul Ummah Prabumulih.</p>', 'Permohonan Kerja Sama Kelembagaan.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'Permohonan Kerja Sama - SMA IT Ishlahul Ummah', 'Kerjasama strategis dan kelembagaan bersama SMA IT Ishlahul Ummah.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (373, 'Permohonan Sewa Menyewa Barang Sekolah', 'sewa-barang', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Layanan dan ketentuan penyewaan fasilitas sekolah (Hall Ishum, laboratorium, perlengkapan event) bagi masyarakat dan instansi.</p>', 'Permohonan Sewa Menyewa Barang / Fasilitas Sekolah.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'Permohonan Sewa Barang - SMA IT Ishlahul Ummah', 'Ketentuan dan permohonan sewa sarana prasarana sekolah.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (374, 'Data Alumni', 'data-alumni', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Daftar alumni kebanggaan SMA IT Ishlahul Ummah Prabumulih yang telah melanjutkan pendidikan ke berbagai perguruan tinggi negeri, kedinasan, kampus Islam terkemuka, dan berkarier di berbagai sektor.</p>', 'Data alumni dan rekam jejak lulusan SMA IT Ishlahul Ummah.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'Data Alumni - SMA IT Ishlahul Ummah Prabumulih', 'Database alumni SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (375, 'Informasi PPDB Online', 'ppdb-sma-it-ishlahul-ummah-prabumulih', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Penerimaan Peserta Didik Baru (PPDB) SMA IT Ishlahul Ummah Prabumulih dibuka setiap tahun ajaran baru dengan jalur beasiswa tahfidz dan reguler. Pendaftaran dapat dilakukan langsung melalui portal online <a href=\"https://ppdb.smaitishumpbm.sch.id/\" target=\"_blank\" class=\"text-green-600 font-bold underline\">https://ppdb.smaitishumpbm.sch.id/</a>.</p>', 'Informasi pendaftaran siswa baru SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'page', NULL, '0', 4, '2026-09-12 07:03:45', 'PPDB SMA IT Ishlahul Ummah Prabumulih', 'Informasi PPDB SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:18', '2026-09-12 08:54:25'),
  (376, 'Juara 4 Sambung Ayat Qur\'an', 'juara-4-sambung-ayat', '<p>Selamat dan sukses atas raihan Juara 4 Sambung Ayat Qur\'an oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.</p>', 'Selamat dan sukses atas raihan Juara 4 Sambung Ayat Qur\'an oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'prestasi', '/uploads/2022/03/35.webp', '0', 4, '2022-03-31 09:12:24', 'Prestasi: Juara 4 Sambung Ayat Qur\'an - SMA IT Ishlahul Ummah', 'Selamat dan sukses atas raihan Juara 4 Sambung Ayat Qur\'an oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:22', '2026-09-12 07:03:22'),
  (377, 'Juara 1 Lomba Kaligrafi', 'juara-1-lomba-kaligrafi', '<p>Selamat dan sukses atas raihan Juara 1 Lomba Kaligrafi oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.</p>', 'Selamat dan sukses atas raihan Juara 1 Lomba Kaligrafi oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'prestasi', '/uploads/2023/01/33.webp', '0', 4, '2023-01-20 15:45:00', 'Prestasi: Juara 1 Lomba Kaligrafi - SMA IT Ishlahul Ummah', 'Selamat dan sukses atas raihan Juara 1 Lomba Kaligrafi oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:22', '2026-09-12 07:03:22'),
  (378, 'Juara 3 Lomba Kaligrafi', 'juara-3-lomba-kaligrafi', '<p>Selamat dan sukses atas raihan Juara 3 Lomba Kaligrafi oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.</p>', 'Selamat dan sukses atas raihan Juara 3 Lomba Kaligrafi oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'prestasi', '/uploads/2023/01/34.webp', '0', 4, '2023-01-23 09:37:22', 'Prestasi: Juara 3 Lomba Kaligrafi - SMA IT Ishlahul Ummah', 'Selamat dan sukses atas raihan Juara 3 Lomba Kaligrafi oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:22', '2026-09-12 07:03:22'),
  (379, 'Juara 3 KSN-K BIOLOGI', 'juara-3-ksn-k-biologi', '<p>Selamat dan sukses atas raihan Juara 3 KSN-K BIOLOGI oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.</p>', 'Selamat dan sukses atas raihan Juara 3 KSN-K BIOLOGI oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', 'publish', 'prestasi', '/uploads/2023/01/ksn-caca.webp', '0', 4, '2023-01-23 09:56:46', 'Prestasi: Juara 3 KSN-K BIOLOGI - SMA IT Ishlahul Ummah', 'Selamat dan sukses atas raihan Juara 3 KSN-K BIOLOGI oleh siswa-siswi SMA IT Ishlahul Ummah Prabumulih.', NULL, '2026-09-12 07:03:22', '2026-09-12 07:03:22'),
