  (56, 'layanan_izin_accordions', '[{\"title\":\"Persyaratan Pelayanan\",\"content\":\"<ul><li>Pemohon memiliki akun pada system untuk melakukan permohonan kunjungan<\\/li><li>Pemohon melakukan pengajuan melalui system<\\/li><li>Bukti permohonan kunjungan sudah di tandatangani oleh yang berwenang dan cap serta dibawa ketika hari kunjungan<\\/li><li>Maksimal pengunjung 100 orang<\\/li><li>Hari kunjungan adalah hari senin dan kamis<\\/li><li>Waktu kunjungan adalah pukul 09.00-11.00 wib<\\/li><li>Pengunjung menggunakan pakaian yang sopan dan rapi<\\/li><li>Wajib menerapkan protkes ketat<\\/li><\\/ul>\"},{\"title\":\"Jangka Waktu Penyelesaian\",\"content\":\"<p>Waktu respon atas permohonan paling lambat 10 (sepuluh) hari kerja<\\/p>\"},{\"title\":\"Biaya dan Tarif\",\"content\":\"<p>Proses permohonan dan pelaksanaan kunjungan tidak dipungut biaya (Gratis)<\\/p>\"},{\"title\":\"Produk Layanan\",\"content\":\"<p>Layanan kunjungan sekolah<\\/p>\"},{\"title\":\"Pengaduan, Saran dan Masukan\",\"content\":\"<p>Pengaduan, saran dan masukan dapat disampaikan ke bagian humas dan media layanan terpadu SMA IT Ishlahul Ummah Prabumulih<\\/p><p>Alamat : Jln. Sadewa RT 01 RW 03 Kel. Krg Raja Prabumulih Timur<\\/p><p>No. HP (WA) : wa.me\\/+62 821-8268-0647<\\/p><p>Website : smaitishumpbm.sch.id<\\/p><p>Email : <a href=\\\"mailto:smaitishlahulummah2019@gmail.com\\\">smaitishlahulummah2019@gmail.com<\\/a><\\/p>\"}]', 'layanan', '2026-09-12 11:32:02', '2026-09-12 11:32:02'),
  (57, 'layanan_kerjasama_accordions', '[{\"title\":\"Persyaratan Pelayanan\",\"content\":\"<ul><li>Surat permohonan dari Pemerintah\\/Swasta\\/Industri\\/Yayasan\\/Organisasi\\/Instansi lainnya.<\\/li><li>Surat permohonan dari Individu (perorangan)<\\/li><\\/ul>\"},{\"title\":\"Sistem Mekanisme dan Prosedur\",\"content\":\"<ul><li>Calon mitra mengajukan surat permohonan ditujukan kepada Kepala Sekolah<\\/li><li>KS memberikan disposisi kepada TU, selanjutnya TU dan\\/atau unit kerja terkait melakukan penilaian kepada calon mitra. Jika disetujui, dilanjutkan dengan pembahasan draft dokumen kerja sama. Jika tidak disetujui, TU akan memberikan surat balasan kepada mitra.<\\/li><li>Pembahasan dan negosiasi draft dokumen kerja sama.<\\/li><li>Pengesahan naskah perjanjian kerja sama.<\\/li><\\/ul>\"},{\"title\":\"Jangka Waktu Penyelesaian\",\"content\":\"<p>Waktu respon atas permohonan paling lambat 10 (sepuluh) hari kerja<\\/p>\"},{\"title\":\"Biaya dan Tarif\",\"content\":\"<p>Gratis<\\/p>\"},{\"title\":\"Produk Layanan\",\"content\":\"<p>Naskah perjanjian kerja sama<\\/p>\"},{\"title\":\"Pengaduan, Saran dan Masukan\",\"content\":\"<p>Pengaduan, saran dan masukan dapat disampaikan ke bagian humas dan media layanan terpadu SMA IT Ishlahul Ummah Prabumulih<\\/p><p>Alamat : Jln. Sadewa RT 01 RW 03 Kel. Krg Raja Prabumulih Timur<\\/p><p>No. HP (WA) : wa.me\\/+62 821-8268-0647<\\/p><p>Website : smaitishumpbm.sch.id<\\/p><p>Email : <a href=\\\"mailto:smaitishlahulummah2019@gmail.com\\\">smaitishlahulummah2019@gmail.com<\\/a><\\/p>\"}]', 'layanan', '2026-09-12 11:32:02', '2026-09-12 11:32:02'),
  (58, 'layanan_sewa_accordions', '[{\"title\":\"Persyaratan Pelayanan\",\"content\":\"<ul><li>Individu (perorangan):<ul><li>Surat Permohonan<\\/li><li>Fotokopi KTP<\\/li><li>Fotokopi NPWP (jika ada)<\\/li><\\/ul><\\/li><li>Lembaga Organisasi:<ul><li>Surat Permohonan<\\/li><li>Fotokopi NPWP<\\/li><\\/ul><\\/li><\\/ul>\"},{\"title\":\"Sistem Mekanisme dan Prosedur\",\"content\":\"<ul><li>Penyewa mengajukan surat permohonan ditujukan kepada kepala sekolah<\\/li><li>Jika permohonan disetujui akan disampaikan penawaran harga kepada Mitra, jika tidak disetujui akan diberitahukan melalui surat pemberitahuan kepada Mitra.<\\/li><li>Melakukan negosiasi harga jika setuju dilanjutkan dengan membuat draf perjanjian sewa menyewa jika tidak setuju akan terjadi pembatalan sewa<\\/li><li>Setelah perjanjian pembayaran sewa ditandatangani Mitra melakukan pembayaran sewa.<\\/li><\\/ul>\"},{\"title\":\"Jangka Waktu Penyelesaian\",\"content\":\"<p>Waktu respon atas permohonan paling lambat 10 (sepuluh) hari kerja<\\/p>\"},{\"title\":\"Biaya dan Tarif\",\"content\":\"<p>Biaya administrasi pelayanan gratis, kecuali biaya pengganti meterai jika penyewa secara individu dan dilakukan secara kolektif.<\\/p>\"},{\"title\":\"Produk Layanan\",\"content\":\"<p>Perjanjian sewa asset<\\/p>\"},{\"title\":\"Pengaduan, Saran dan Masukan\",\"content\":\"<p>Pengaduan, saran dan masukan dapat disampaikan ke bagian humas dan media layanan terpadu SMA IT Ishlahul Ummah Prabumulih<\\/p><p>Alamat : Jln. Sadewa RT 01 RW 03 Kel. Krg Raja Prabumulih Timur<\\/p><p>No. HP (WA) : wa.me\\/+62 821-8268-0647<\\/p><p>Website : smaitishumpbm.sch.id<\\/p><p>Email : <a href=\\\"mailto:smaitishlahulummah2019@gmail.com\\\">smaitishlahulummah2019@gmail.com<\\/a><\\/p>\"}]', 'layanan', '2026-09-12 11:32:02', '2026-09-12 11:32:02');
