INSERT INTO `testimonials` (`id`, `name`, `profession`, `content`, `photo`, `status`, `created_at`, `updated_at`) VALUES
  (1, 'Eva Astuti', 'Wali Siswa SMA IT Ishum', 'Anakku bernama Abdurrosyad Fadlillah saat ini duduk di kelas XI Al-Quds. Alhamdulillah skrg sdh mulai berani tampil walau kdg2 msh kurang pede, bs lebih sopan n santun skrg. Smg dg sisa wkt yg lebih kurang 1,5 thn kedepan dg bantuan n bimbingan dari ustad/zah kk bisa lebih percaya diri lg, bisa lebih tau apa yg diinginkan sehingga bs membuat keputusan sendiri, mau berusaha lebih keras lg n lebih disiplin waktu. Aamiinn', '/uploads/2022/11/aa-e1669180943813.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (2, 'Ayu Putri', 'Wali Siswa SMA IT Ishum', 'Toby aldinata timothy anakku siswa baru tahun ini. Semoga yang baik menjadi lebih baik lagi.n', '/uploads/2022/11/ab-e1669180894929.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (3, 'Evi Riani', 'Wali Siswa SMA IT Ishum', 'Putri sulungku Seren Rahmadani saat ini di kelas akhir. Alhamdulillah ada perubahan yang terus signifikan, semoga anakku istiqomah dalam ibadah, berakhlah mulia dan beradab.n', '/uploads/2022/11/z-e1669181074941.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (4, 'Penny Cahyani', 'Wali Siswa SMA IT Ishum', 'Najwa rizkiya ramadhani nama putriku yang saat ini duduk di kelas akhir. Semoga setelah lulus dari SMA IT ananda bisa menjadi anak sukses dan berakhlak mulia.n', '/uploads/2022/11/zz-e1669181127751.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (5, 'Yulianti Widiastuti', 'Wali Siswa SMA IT Ishum', 'Anakku bernama Annisa dhiya abelia, saat ini sudah kelas XII Gaza. Anak mulai PD, hafalannya semakin bagus, selalu melakukan hal dengan mengingat agama sehingga ia selalu hati2 dlm bertindak.n', '/uploads/2022/04/wa-e1669181180765.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (6, 'Dora Indah', 'Wali Siswa SMA IT Ishum', 'Anakku bernama Ragil rizgy putra yang sudah duduk di kelas XI Al-Quds. Saya merasa membuat pilihan yang sangat tepat meletakkan dan menitipkan anak saya disini...pesan kami sebagai orang tua adalah anggap anak kami adalah bagian dari keluarga besar islahul ummah..sehingga para orang tua yang disekolah benar2 merasakan dan memiliki harapan yang sama dengan kami..unt mengantarkan anak2 kita kegerbang sukses dunia dan akhiratnya aamiinnn', '/uploads/2022/11/20221104-152813-dora-indah-e1669708484674.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (7, 'Suharyanti', 'Wali Siswa SMA IT Ishum', 'Abi anggara santriyano adalah anak laki-lakiku yang saat ini duduk di kelas XII Gaza. .semoga tetap mengutamakan kwalitas pendidikan agama nya agar tercipta nya siswa/siswi yg berakhlak mulia aamiin..dan untuk para pengajar nya tetap memberikan perhatian yg ter baik untuk anak2 ,semoga allah memudah kan dan melancar kan setiap masalah dan diberkahi allah subhanahu waataala aamiin.nn', '/uploads/2022/11/img-20220316-wa0010-alqauzza-anggrayano-e1669708419526.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (8, 'Sugiarti', 'Wali Siswa SMA IT Ishum', 'Setelah 3 tahun di SMAIT Ishlahul Ummah, saya dan ibu saya mearasa bahwa saya bisa lebih disiplin dalam hal ibadah dari sebelumnya, dan juga ilmu yang saya dapat tentang agama islam juga lebih banyak dari sebelumnya, karena di SMAIT Ishlahul Ummah saya mendapatkan ilmu bukan hanya dari ustad dan ustadzahnya saja melainkan dari teman-teman saya yang selalu mau membagikan ilmunya kepada sayan', '/uploads/2024/07/img-20240702-wa0015-rotated.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:45'),
  (9, 'Shella Destiani', 'Wali Siswa SMA IT Ishum', 'Shella Destiani, saat ini sedang Kursus di LPMKA YKPP, Jurusan Adm. PerkantorannSekolah di SMA IT menurut saya berbeda dari sekolah lain, terutama tentang lingkungan pertemanan, yang tidak ada yang namanya senioritas, dan itu membuat saya sangat suka berada di lingkungan ini, semua gurunya selalu memotivasi saya, terutama untuk mendapatkan nilai yang lebih baik lagi, ada beberapa yang saya suka dengan guru disini, karena kepeduliannya, bisa di ajak bercerita tentang masalah atau suatu hal yang sulit untuk dijalani oleh muridnya, yang paling saya suka, ada 1 guru juga di SMA IT yang sangat saya kagumi, dia guru yang mungkin umurnya tidak terlalu jauh dari kami, dengan dia kami selalu bercerita banyak hal tanpa ragu, dia memberikan saran dan juga bisa mendengarkan kritik yang selalu kami berikan, dan dia adalah guru yang sangat sabar. Makasi ust/z!!!nHarapan saya untuk sekolah ini, semoga sekolah ini menjadi sekolah yang maju, muridnya makin banyak, murid”nya juga semoga makin banyak yang bisa berinisiatif dalam hal apapun, semoga semua guru bisa mendengarkan dan memberikan saran tanpa menjatuhkan saran dari seorang murid, karena walaupun seorang murid perlu juga didengarkan sarannya, semoga cepat pindah ke gedung baru yeayy, organisasinya berjalan lancar tanpa ada kendala yang terjadi di tahun” sebelumnya, semoga semua guru dan muridnya sukses!!!n&nbsp;nn', '/uploads/2022/11/edae9f28-48f4-4e75-987a-87e654c2ca4f-shella-destiani-e1669708636134.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (10, 'Toni Siswanto dan Widyaningtyastuti', 'Wali Siswa SMA IT Ishum', 'Assalamu\'alaykum warahmatullahi wabarakatuh.. Kami Orang tua dari ananda Yunita Andini Amalia. Alhamdulillah ananda Yunita bersekolah di SMAIT Ishlahul Ummah. Sekolah Ishlahul Ummah mendidik sepenuh cinta berkarakter islami. bukan hanya dibekali ilmu pengetahuan umum, tetapi anak kami dibekali juga dengan Tahfiz dan Tahsin. metode belajarnya juga tidak membosankan. Guru-guru nya yang tegas dan ramah dan teman-teman yang baik dan suportif. Alhamdulillah Insyaallah lingkungannya terjaga.n', '/uploads/2024/07/img-20240702-wa0016.webp', 'publish', '2026-09-11 15:07:22', '2026-09-12 07:03:23'),
  (11, 'Sugiarti', 'Wali Murid SMA IT Ishum', 'Setelah 3 tahun di SMAIT Ishlahul Ummah, saya dan ibu saya mearasa bahwa saya bisa lebih disiplin dalam hal ibadah dari sebelumnya, dan juga ilmu yang saya dapat tentang agama islam juga lebih banyak dari sebelumnya, karena di SMAIT Ishlahul Ummah saya mendapatkan ilmu bukan hanya dari ustad dan ustadzahnya saja melainkan dari teman-teman saya yang selalu mau membagikan ilmunya kepada saya', '/uploads/ishum/testi_3225_IMG-20240702-WA0015-rotated.webp', 'publish', '2026-09-11 15:07:22', '2026-09-11 15:07:22');
